-- rowstile 0.1.0-alpha.6: policy. Generated by rowstile migrate from the policy; don't edit it,
-- change the policy and write the next migration.
-- the whole policy (17 lines)

-- a migration is one transaction: outside one, nothing below changes anything
SELECT pg_catalog.set_config('authz_ctx.migration', 'ab9771beda4bd3dd', true);
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'ab9771beda4bd3dd' THEN
    PERFORM pg_catalog.set_config('default_transaction_read_only', 'on', false);
  END IF;
END $authz_tx$;
DO $authz_tx$
BEGIN
  IF pg_catalog.current_setting('authz_ctx.migration', true) IS DISTINCT FROM 'ab9771beda4bd3dd' THEN
    RAISE EXCEPTION 'rowstile: this migration must run in one transaction, and its statements are being committed one by one [AZ615]'
      USING HINT = 'nothing was changed, and this session is read-only from here on; run the file with your migration tool, or with psql -1 -f';
  END IF;
END $authz_tx$;

SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');
SELECT pg_catalog.set_config('check_function_bodies', 'off', true);

-- Generated by rowstile from the policy. Edit the policy file, not this file.

-- Applying locks the app's tables. Wait for them 10 s at most (unless lock_timeout is set) instead
-- of queueing every query behind this transaction on a busy database; retry when it is quieter
SELECT pg_catalog.set_config('lock_timeout', '10s', true) WHERE pg_catalog.current_setting('lock_timeout') IN ('0', '0ms');

-- Functions below resolve names with the search_path in effect now: the schemas that exist, temporary schema last
DO $sp$
DECLARE v_path text; v_bad text; f record;
BEGIN
  SELECT pg_catalog.string_agg(pg_catalog.format('%I (%s)', pw.schema, pw.who), ', ') INTO v_bad FROM (SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, CURRENT_USER, 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_') pw;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'the search path has schemas that roles other than the owner may create objects in: % [AZ612]', v_bad
      USING HINT = 'rowstile''s functions that run as the owner resolve names on this path, so a function made there could run as the owner: revoke CREATE on those schemas, or apply with a search path without them';
  END IF;
  SELECT pg_catalog.string_agg(pg_catalog.quote_ident(s.name), ', ' ORDER BY s.i) INTO v_path
  FROM pg_catalog.unnest(pg_catalog.current_schemas(false)) WITH ORDINALITY s(name, i)
  WHERE s.name::text !~ '^pg_temp_';
  PERFORM pg_catalog.set_config('search_path', pg_catalog.concat_ws(', ', v_path, 'pg_temp'), true);
  -- functions made before (a migration keeps those it doesn't change) take the same path
  FOR f IN SELECT p.oid::regprocedure AS fn FROM pg_catalog.pg_proc p
           WHERE p.pronamespace IN (SELECT n.oid FROM pg_catalog.pg_namespace n WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int'))
             AND EXISTS (SELECT 1 FROM pg_catalog.unnest(p.proconfig) c
                         WHERE c ^@ 'search_path=' AND c <> 'search_path=pg_catalog, pg_temp'
                           AND c <> 'search_path=' || pg_catalog.current_setting('search_path')) LOOP
    EXECUTE pg_catalog.format('ALTER FUNCTION %s SET search_path FROM CURRENT', f.fn);
  END LOOP;
END $sp$;

DROP TABLE IF EXISTS pg_temp.authz_old_tables;

-- Remove the policies the previous version of this policy made (remembering their tables)
CREATE TEMP TABLE authz_old_tables ON COMMIT DROP AS
  SELECT DISTINCT p.polrelid::regclass AS tbl
  FROM pg_policy p
  LEFT JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
  WHERE d.description IN ('rowstile', 'rowfence', 'authzc') OR p.polname IN ('authz_select', 'authz_insert', 'authz_update', 'authz_delete');
DO $d$
DECLARE old record;
BEGIN
  FOR old IN SELECT pol.polname, pol.polrelid::regclass AS tbl
             FROM pg_policy pol
             LEFT JOIN pg_description d ON d.objoid = pol.oid AND d.classoid = 'pg_policy'::regclass
             WHERE d.description IN ('rowstile', 'rowfence', 'authzc') OR pol.polname IN ('authz_select', 'authz_insert', 'authz_update', 'authz_delete') LOOP
    EXECUTE format('DROP POLICY %I ON %s', old.polname, old.tbl);
  END LOOP;
END $d$;

-- The masked views the previous version made are made again; one that something is built on stays, emptied
DO $mv$
DECLARE v record; cols text;
BEGIN
  FOR v IN SELECT c.oid, c.oid::regclass AS name FROM pg_class c JOIN pg_description d ON d.objoid = c.oid
           AND d.classoid = 'pg_class'::regclass WHERE c.relkind = 'v' AND d.description IN ('rowstile masked view', 'rowfence masked view', 'authzc masked view') LOOP
    BEGIN
      EXECUTE format('DROP VIEW %s', v.name);
    EXCEPTION WHEN dependent_objects_still_exist THEN
      SELECT (SELECT string_agg(format('NULL::%s%s AS %I', pg_catalog.format_type(a.atttypid, a.atttypmod),
        CASE WHEN a.attcollation <> 0 AND a.attcollation <> t.typcollation
             THEN format(' COLLATE %I.%I', cn.nspname, co.collname) ELSE '' END, a.attname), ', ' ORDER BY a.attnum)
      FROM pg_catalog.pg_attribute a JOIN pg_catalog.pg_type t ON t.oid = a.atttypid
      LEFT JOIN pg_catalog.pg_collation co ON co.oid = a.attcollation
      LEFT JOIN pg_catalog.pg_namespace cn ON cn.oid = co.collnamespace
      WHERE a.attrelid = v.oid AND a.attnum > 0 AND NOT a.attisdropped) INTO cols;
      EXECUTE format('CREATE OR REPLACE VIEW %s AS SELECT %s WHERE false', v.name, cols);
    END;
  END LOOP;
END $mv$;

-- Inheritance tables that don't change keep their rows: moved aside now, back after the schema is recreated
DROP TABLE IF EXISTS pg_temp.authz_kept;
CREATE TEMP TABLE authz_kept (name text PRIMARY KEY) ON COMMIT DROP;
DROP SCHEMA IF EXISTS authz_keep CASCADE;
CREATE SCHEMA authz_keep;
DO $keep$
DECLARE r record;
BEGIN
  IF to_regclass('authz_int.trees') IS NULL THEN RETURN; END IF;          -- the first apply
  FOR r IN SELECT t.name FROM authz_int.trees t
           JOIN (VALUES (NULL::text, NULL::text, NULL::oid[])) n(name, hash, oids)
             ON n.name = t.name AND n.hash = t.hash AND n.oids = t.oids
           WHERE to_regclass(format('authz_int.%I', t.name)) IS NOT NULL LOOP
    EXECUTE format('ALTER TABLE authz_int.%I SET SCHEMA authz_keep', r.name);
    IF to_regclass(format('authz_int.%I', r.name || '_cond_cache')) IS NOT NULL THEN
      EXECUTE format('ALTER TABLE authz_int.%I SET SCHEMA authz_keep', r.name || '_cond_cache');
    END IF;
  END LOOP;
END $keep$;

DROP SCHEMA IF EXISTS authz_gen, authz_int CASCADE;

-- Functions this policy generates are recreated (whatever their old signatures). One that something of
-- the app's uses (a view that calls authz.can) stays, to be replaced in place
DO $g$
DECLARE f record; kept text := '';
BEGIN
  FOR f IN SELECT p.oid, p.ctid, p.oid::regprocedure AS name FROM pg_proc p WHERE p.pronamespace = to_regnamespace('authz')
           AND p.proname = ANY (ARRAY['act_as', 'can', 'list', 'perms', 'perms_of', 'share', 'unshare', 'verify', 'create_link', 'principal', 'create_role', 'set_role_permissions', 'delete_role', 'roles_of', 'who', 'explain', 'list_shares', 'shares', 'create_api_key', 'list_api_keys', 'revoke_api_key', 'login_key', 'login_jwt', 'view_as', 'sync_members', 'changes_since', 'trim_changes', 'trim_audit', 'request_access', 'pending_requests', 'decide_request', 'cancel_request', 'break_glass', 'start_review', 'review_items', 'review_decide', 'close_review', 'check_invariants', 'lint', 'connection_check', 'explain_rule', 'who_among', 'list_links', 'revoke_link']) LOOP
    BEGIN
      EXECUTE format('DROP FUNCTION %s', f.name);
    EXCEPTION WHEN dependent_objects_still_exist THEN
      kept := kept || f.oid || ' ' || f.ctid || ';';
    END;
  END LOOP;
  PERFORM set_config('authz_ctx.kept_functions', kept, true);
END $g$;

-- Base objects (kept across re-applies)
CREATE SCHEMA IF NOT EXISTS authz;
REVOKE ALL ON SCHEMA authz FROM PUBLIC;

-- 0.1.0 renamed authz.grants to authz.shares
DO $mg$
BEGIN
  IF to_regclass('authz.grants') IS NOT NULL AND to_regclass('authz.shares') IS NULL THEN
    ALTER TABLE authz.grants RENAME TO shares;
    ALTER TABLE authz.shares RENAME CONSTRAINT grants_pkey TO shares_pkey;
    ALTER INDEX IF EXISTS authz.grants_by_subject RENAME TO shares_by_subject;
  END IF;
END $mg$;

-- Shares people create in the app, for relations marked 'shared' (and custom role assignments)
CREATE TABLE IF NOT EXISTS authz.shares (
  object_type      text        NOT NULL,
  object_id        text        NOT NULL,
  relation         text        NOT NULL,
  subject_type     text        NOT NULL,
  subject_id       text        NOT NULL,
  subject_relation text        NOT NULL DEFAULT '',
  expires_at       timestamptz,
  created_by       text,
  starts_at        timestamptz,
  caveat           text,
  caveat_args      jsonb,
  created_at       timestamptz DEFAULT now(),
  PRIMARY KEY (object_type, object_id, relation, subject_type, subject_id, subject_relation));
-- earlier versions stored integer ids
DO $m$
BEGIN
  IF (SELECT atttypid FROM pg_attribute WHERE attrelid = 'authz.shares'::regclass AND attname = 'object_id') <> 'text'::regtype THEN
    ALTER TABLE authz.shares ALTER COLUMN object_id TYPE text USING object_id::text,
                             ALTER COLUMN subject_id TYPE text USING subject_id::text,
                             ALTER COLUMN created_by TYPE text USING created_by::text;
  END IF;
END $m$;
ALTER TABLE authz.shares ADD COLUMN IF NOT EXISTS starts_at timestamptz;
ALTER TABLE authz.shares ADD COLUMN IF NOT EXISTS caveat text;
ALTER TABLE authz.shares ADD COLUMN IF NOT EXISTS caveat_args jsonb;
ALTER TABLE authz.shares ADD COLUMN IF NOT EXISTS created_at timestamptz DEFAULT now();
CREATE INDEX IF NOT EXISTS shares_by_subject
  ON authz.shares (subject_type, subject_id, subject_relation, object_type, relation);
REVOKE ALL ON authz.shares FROM PUBLIC;

-- Custom roles: sets of permissions defined as data, assigned like shares ('role:<id>')
CREATE TABLE IF NOT EXISTS authz.roles (
  id          bigserial PRIMARY KEY,
  owner_type  text NOT NULL,
  owner_id    text NOT NULL,
  object_type text NOT NULL,
  name        text NOT NULL,
  created_by  text,
  created_at  timestamptz DEFAULT now(),
  UNIQUE (owner_type, owner_id, object_type, name));
CREATE TABLE IF NOT EXISTS authz.role_permissions (
  role_id    bigint NOT NULL REFERENCES authz.roles ON DELETE CASCADE,
  permission text   NOT NULL,
  PRIMARY KEY (role_id, permission));
REVOKE ALL ON authz.roles, authz.role_permissions FROM PUBLIC;

-- API keys (only a hash of each is kept)
CREATE TABLE IF NOT EXISTS authz.api_keys (
  id           bigserial PRIMARY KEY,
  user_id      text NOT NULL,
  name         text NOT NULL,
  prefix       text NOT NULL,
  hash         text NOT NULL UNIQUE,
  scopes       text NOT NULL DEFAULT '',
  created_at   timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz,
  last_used_at timestamptz,
  revoked_at   timestamptz);
-- whose key: user_id is the principal's id, of this type
ALTER TABLE authz.api_keys ADD COLUMN IF NOT EXISTS principal_type text NOT NULL DEFAULT 'user';
-- Settings for the functions (jwt_secret, jwt_issuer, jwt_audience, jwt_user_claim, jwt_type_claim, ...)
CREATE TABLE IF NOT EXISTS authz.settings (key text PRIMARY KEY, value text NOT NULL);
-- The audit trail: every share, role, key, request and impersonation, and relationship changes
CREATE TABLE IF NOT EXISTS authz.audit (
  id               bigserial PRIMARY KEY,
  at               timestamptz NOT NULL DEFAULT clock_timestamp(),
  txid             bigint NOT NULL DEFAULT txid_current(),
  db_role          text,
  user_id          text,
  acting_user      text,
  action           text NOT NULL,
  object_type      text,
  object_id        text,
  relation         text,
  subject_type     text,
  subject_id       text,
  subject_relation text,
  detail           jsonb,
  reason           text);
CREATE INDEX IF NOT EXISTS audit_by_object ON authz.audit (object_type, object_id, at);
REVOKE ALL ON authz.api_keys, authz.settings, authz.audit FROM PUBLIC;

-- Change feed: objects whose access may have changed, for caches, search indexes, file stores
CREATE TABLE IF NOT EXISTS authz.changes (
  pos         bigserial PRIMARY KEY,
  at          timestamptz NOT NULL DEFAULT clock_timestamp(),
  txid        bigint NOT NULL DEFAULT txid_current(),
  object_type text NOT NULL,
  object_ids  text[] NOT NULL,
  cause       text NOT NULL);
-- Access requests, approvals, and emergency access
CREATE TABLE IF NOT EXISTS authz.requests (
  id          bigserial PRIMARY KEY,
  object_type text NOT NULL,
  object_id   text NOT NULL,
  relation    text NOT NULL,
  requester   text NOT NULL,
  reason      text,
  duration    interval,
  status      text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'denied', 'cancelled')),
  decided_by  text,
  decided_at  timestamptz,
  note        text,
  created_at  timestamptz NOT NULL DEFAULT now());
-- Access reviews: a snapshot of the shares on an object, each kept or revoked by a reviewer
CREATE TABLE IF NOT EXISTS authz.reviews (
  id          bigserial PRIMARY KEY,
  object_type text NOT NULL,
  object_id   text NOT NULL,
  created_by  text,
  created_at  timestamptz NOT NULL DEFAULT now(),
  closes_at   timestamptz,
  closed_at   timestamptz);
CREATE TABLE IF NOT EXISTS authz.review_items (
  review_id        bigint NOT NULL REFERENCES authz.reviews ON DELETE CASCADE,
  item             int    NOT NULL,
  relation         text   NOT NULL,
  subject_type     text   NOT NULL,
  subject_id       text   NOT NULL,
  subject_relation text   NOT NULL,
  expires_at       timestamptz,
  keep             boolean,
  decided_by       text,
  decided_at       timestamptz,
  PRIMARY KEY (review_id, item));
-- Tables whose table-wide SELECT was replaced by column privileges because of masks
CREATE TABLE IF NOT EXISTS authz.masked_tables (tbl text, role text, PRIMARY KEY (tbl, role));
REVOKE ALL ON authz.changes, authz.requests, authz.reviews, authz.review_items, authz.masked_tables FROM PUBLIC;

-- Every policy the rowstile command applied or removed, with the rowstile version that did it
CREATE TABLE IF NOT EXISTS authz.policy_versions (
  id      bigserial PRIMARY KEY,
  at      timestamptz NOT NULL DEFAULT now(),
  by_role text NOT NULL DEFAULT current_user,
  action  text NOT NULL CHECK (action IN ('apply', 'remove')),
  policy  text,
  files   jsonb NOT NULL DEFAULT '{}',
  version text NOT NULL);
-- 0.1.0 kept it in the extension, as extension_version
DO $pv$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'authz.policy_versions'::regclass
             AND attname = 'extension_version' AND NOT attisdropped) THEN
    ALTER TABLE authz.policy_versions RENAME COLUMN extension_version TO version;
  END IF;
END $pv$;
-- what the migrations' lock file said about this policy (its hash), for the next migration to check
ALTER TABLE authz.policy_versions ADD COLUMN IF NOT EXISTS lock text;
REVOKE ALL ON authz.policy_versions FROM PUBLIC;

-- Request context for conditions: SET LOCAL authz_ctx.mfa = 'yes', then {authz.ctx('mfa') = 'yes'}
CREATE OR REPLACE FUNCTION authz.ctx(key text) RETURNS text LANGUAGE sql STABLE AS
  $$ SELECT current_setting('authz_ctx.' || key, true) $$;

-- Link tokens the request presents: SET LOCAL authz_ctx.links = '<token>,<token>'
CREATE OR REPLACE FUNCTION authz.link_hashes() RETURNS text[] LANGUAGE sql STABLE AS $$
  SELECT coalesce(array_agg(encode(sha256(convert_to(btrim(x), 'UTF8')), 'hex')), '{}')
  FROM unnest(string_to_array(nullif(current_setting('authz_ctx.links', true), ''), ',')) x
  WHERE btrim(x) <> '' $$;

DO $chk$
DECLARE missing text := '';
BEGIN
  IF to_regclass('"app"."users"') IS NULL THEN missing := missing || E'\n  line 5: table app.users not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."users"')
                    AND attname = 'id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 5: column id not found in app.users [AZ601]';
  END IF;
  IF to_regclass('"app"."teams"') IS NULL THEN missing := missing || E'\n  line 7: table app.teams not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."teams"')
                    AND attname = 'id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 7: column id not found in app.teams [AZ601]';
  END IF;
  IF to_regclass('"app"."team_members"') IS NULL THEN missing := missing || E'\n  line 8: table app.team_members not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."team_members"')
                    AND attname = 'team_id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 8: column team_id not found in app.team_members [AZ601]';
  END IF;
  IF to_regclass('"app"."team_members"') IS NULL THEN missing := missing || E'\n  line 8: table app.team_members not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."team_members"')
                    AND attname = 'user_id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 8: column user_id not found in app.team_members [AZ601]';
  END IF;
  IF to_regclass('"app"."documents"') IS NULL THEN missing := missing || E'\n  line 10: table app.documents not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."documents"')
                    AND attname = 'id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 10: column id not found in app.documents [AZ601]';
  END IF;
  IF to_regclass('"app"."documents"') IS NULL THEN missing := missing || E'\n  line 11: table app.documents not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."documents"')
                    AND attname = 'owner_id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 11: column owner_id not found in app.documents [AZ601]';
  END IF;
  IF to_regclass('"app"."documents"') IS NULL THEN missing := missing || E'\n  line 23: table app.documents not found [AZ601]';
  ELSIF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = to_regclass('"app"."documents"')
                    AND attname = 'owner_id' AND attnum > 0 AND NOT attisdropped) THEN
    missing := missing || E'\n  line 23: column owner_id not found in app.documents [AZ601]';
  END IF;
  IF to_regclass('"app"."users"') IS NOT NULL AND (SELECT atttypid FROM pg_attribute WHERE attrelid = to_regclass('"app"."users"') AND attname = 'id') <> to_regtype('bigint') THEN
    missing := missing || E'\n  line 5: app.users.id is not bigint; write its type after the key, e.g. (id uuid) [AZ602]';
  END IF;
  IF to_regclass('"app"."teams"') IS NOT NULL AND (SELECT atttypid FROM pg_attribute WHERE attrelid = to_regclass('"app"."teams"') AND attname = 'id') <> to_regtype('bigint') THEN
    missing := missing || E'\n  line 7: app.teams.id is not bigint; write its type after the key, e.g. (id uuid) [AZ602]';
  END IF;
  IF to_regclass('"app"."documents"') IS NOT NULL AND (SELECT atttypid FROM pg_attribute WHERE attrelid = to_regclass('"app"."documents"') AND attname = 'id') <> to_regtype('bigint') THEN
    missing := missing || E'\n  line 10: app.documents.id is not bigint; write its type after the key, e.g. (id uuid) [AZ602]';
  END IF;
  IF missing <> '' THEN RAISE EXCEPTION 'the policy does not match this database:%', missing; END IF;
END $chk$;

-- Who is asking: SELECT authz.act_as('user', '42') first in each transaction (a signed session).
-- An id the user table doesn't have counts as nobody.
DO $u$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_proc WHERE oid = to_regprocedure('authz.uid()')
             AND prorettype <> 'bigint'::regtype) THEN
    RAISE EXCEPTION 'authz.uid() returns another type than this policy''s user ids (bigint); drop it first (DROP FUNCTION authz.uid() CASCADE drops what uses it) [AZ606]';
  END IF;
END $u$;

CREATE OR REPLACE FUNCTION authz.uid() RETURNS bigint LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $uid$ BEGIN RETURN (SELECT u."id" FROM "app"."users" u WHERE u."id" = (CASE WHEN authz_int.session_ok() AND coalesce(pg_catalog.current_setting('authz.principal_type', true), '') IN ('', 'user') AND pg_catalog.pg_input_is_valid(pg_catalog.current_setting('authz.user_id', true), 'bigint') THEN pg_catalog.current_setting('authz.user_id', true)::bigint END)); END $uid$;

CREATE SCHEMA authz_gen;
CREATE SCHEMA authz_int;

-- Signed sessions: the key, made once and kept in authz.settings (the app role can't read either)
CREATE TABLE authz_int.session_key (ipad bytea NOT NULL, opad bytea NOT NULL);
INSERT INTO authz.settings (key, value)
  VALUES ('session_key', replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', ''))
  ON CONFLICT (key) DO NOTHING;
DO $sk$
DECLARE k bytea; i bytea; o bytea;
BEGIN
  SELECT decode(value, 'hex') INTO k FROM authz.settings WHERE key = 'session_key';
  k := k || decode(repeat('00', 64 - length(k)), 'hex');
  i := k; o := k;
  FOR n IN 0..63 LOOP
    i := set_byte(i, n, get_byte(k, n) # 54);
    o := set_byte(o, n, get_byte(k, n) # 92);
  END LOOP;
  INSERT INTO authz_int.session_key VALUES (i, o);
END $sk$;
-- HMAC-SHA256 of who is signed in, this backend and this transaction
CREATE FUNCTION authz_int.session_sig() RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key;
BEGIN
  SELECT * INTO k FROM authz_int.session_key;
  RETURN pg_catalog.encode(pg_catalog.sha256(k.opad || pg_catalog.sha256(k.ipad || pg_catalog.convert_to(pg_catalog.concat_ws(pg_catalog.chr(31), coalesce(pg_catalog.current_setting('authz.user_id', true), ''), coalesce(pg_catalog.current_setting('authz.principal_type', true), ''), coalesce(pg_catalog.current_setting('authz.scopes', true), ''), coalesce(pg_catalog.current_setting('authz.acting_user', true), ''), pg_catalog.pg_backend_pid()::text, (EXTRACT(epoch FROM pg_catalog.transaction_timestamp()) * 1000000)::bigint::text), 'UTF8'))), 'hex');
END $f$;
-- signs the settings as they are now: for rowstile's own functions, after they switch who is signed in
CREATE FUNCTION authz_int.sign() RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM set_config('authz.session', authz_int.session_sig(), true);
END $f$;
-- Are the settings to be believed? PL/pgSQL, so its plans are kept for the session, and not a definer: all its
-- callers run as the owner. (OR runs left to right: the refusal is asked only when the signature doesn't match.)
CREATE FUNCTION authz_int.session_ok() RETURNS boolean
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz_int.session_key;
BEGIN
  SELECT * INTO k FROM authz_int.session_key;
  RETURN coalesce(current_setting('authz.session', true) = pg_catalog.encode(pg_catalog.sha256(k.opad || pg_catalog.sha256(k.ipad || pg_catalog.convert_to(pg_catalog.concat_ws(pg_catalog.chr(31), coalesce(pg_catalog.current_setting('authz.user_id', true), ''), coalesce(pg_catalog.current_setting('authz.principal_type', true), ''), coalesce(pg_catalog.current_setting('authz.scopes', true), ''), coalesce(pg_catalog.current_setting('authz.acting_user', true), ''), pg_catalog.pg_backend_pid()::text, (EXTRACT(epoch FROM pg_catalog.transaction_timestamp()) * 1000000)::bigint::text), 'UTF8'))), 'hex'), false) OR authz_int.session_refused();
END $f$;
-- When the signature doesn't match: true for the owner's and superusers' sessions, else an error saying why
CREATE FUNCTION authz_int.session_refused() RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_sig text := coalesce(current_setting('authz.session', true), '');
BEGIN
  -- the policy's owner and superusers say who is signed in by setting it (psql, migrations, tests)
  IF pg_has_role(session_user, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER') THEN
    RETURN true;
  END IF;
  IF v_sig <> '' THEN
    RAISE EXCEPTION 'who is signed in was changed after signing in' USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'say who is signed in with authz.act_as(), never by setting authz.user_id or the other authz settings '
             '(rowstile help AZ702)';
  ELSIF coalesce(current_setting('authz.user_id', true), '') <> '' THEN
    RAISE EXCEPTION 'authz.user_id was set directly, so it is not believed' USING ERRCODE = 'invalid_authorization_specification',
      HINT = 'sign in with SELECT authz.act_as(''user'', ''42''), authz.login_key() or authz.login_jwt() (rowstile help AZ702)';
  END IF;
  RAISE EXCEPTION 'nobody signed in in this transaction' USING ERRCODE = 'invalid_authorization_specification',
    HINT = 'start each transaction with SELECT authz.act_as(''user'', ''42''), or authz.act_as(NULL, NULL) for nobody '
           '(or authz.login_key() / authz.login_jwt()) (rowstile help AZ701)';
END $f$;

-- an id as it is stored and compared: '(1, 42)' -> '(1,42)', '007' -> '7' (invalid ids as they are)
CREATE FUNCTION authz_int.canon(p_type text, p_id text) RETURNS text
LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  CASE p_type
    WHEN 'user' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'team' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    WHEN 'document' THEN
      IF pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN p_id::bigint::text; END IF;
    ELSE NULL;
  END CASE;
  RETURN p_id;
END $f$;
-- shares written directly get canonical ids too
CREATE FUNCTION authz_int.shares_canon() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  NEW.object_id := authz_int.canon(NEW.object_type, NEW.object_id);
  NEW.subject_id := authz_int.canon(NEW.subject_type, NEW.subject_id);
  RETURN NEW;
END $f$;
CREATE TRIGGER authz_shares_canon BEFORE INSERT OR UPDATE OF object_type, object_id, subject_type, subject_id
  ON authz.shares FOR EACH ROW EXECUTE FUNCTION authz_int.shares_canon();

-- Who is signed in, whatever their type: SELECT * FROM authz.principal()
CREATE OR REPLACE FUNCTION authz.principal() RETURNS TABLE (principal_type text, principal_id text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  principal_type := coalesce(nullif(pg_catalog.current_setting('authz.principal_type', true), ''), 'user');
  CASE principal_type
    WHEN 'user' THEN principal_id := authz.uid()::text;
    ELSE RETURN;
  END CASE;
  IF principal_id IS NOT NULL THEN RETURN NEXT; END IF;
END $f$;
-- how the audit trail and created_by name who acted: a user's id, or type:id for other principals
CREATE FUNCTION authz_int.actor() RETURNS text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  RETURN CASE WHEN NOT authz_int.session_ok() THEN NULL
              WHEN coalesce(pg_catalog.current_setting('authz.principal_type', true), '') IN ('', 'user') THEN nullif(current_setting('authz.user_id', true), '')
              ELSE pg_catalog.current_setting('authz.principal_type', true) || ':' || nullif(current_setting('authz.user_id', true), '') END;
END $f$;

-- per type: its table, key, how to find a row x by an id ($1, text), and a row's id (columns unqualified)
CREATE TABLE authz_int.types (name text PRIMARY KEY, tbl text NOT NULL, pk text NOT NULL, pktype text NOT NULL,
  keytype text NOT NULL, find text NOT NULL, id_of text NOT NULL, principal boolean NOT NULL);

INSERT INTO authz_int.types VALUES
  ('user', '"app"."users"', 'id', 'bigint', 'bigint', 'x."id" = $1::bigint', '"id"::text', true),
  ('team', '"app"."teams"', 'id', 'bigint', 'bigint', 'x."id" = $1::bigint', '"id"::text', false),
  ('document', '"app"."documents"', 'id', 'bigint', 'bigint', 'x."id" = $1::bigint', '"id"::text', false);

CREATE TABLE authz_int.perms (type text, perm text, PRIMARY KEY (type, perm));

INSERT INTO authz_int.perms VALUES
  ('document', 'share'),
  ('document', 'edit'),
  ('document', 'view');

CREATE TABLE authz_int.locks (type text PRIMARY KEY, n bigint NOT NULL);

-- each inheritance table's definition and the tables it reads, to keep it on the next apply if they are the same
CREATE TABLE authz_int.trees (name text PRIMARY KEY, hash text NOT NULL, oids oid[] NOT NULL);

CREATE TABLE authz_int.shared_relations (object_type text, relation text, subject text, shared_by text, required text[], loc text, PRIMARY KEY (object_type, relation, subject));

INSERT INTO authz_int.shared_relations VALUES
  ('document', 'editor', 'user', 'share', ARRAY['edit', 'view']::text[], 'share document.editor user'),
  ('document', 'editor', 'team#member', 'share', ARRAY['edit', 'view']::text[], 'share document.editor team#member'),
  ('document', 'viewer', 'user', 'share', ARRAY['view']::text[], 'share document.viewer user'),
  ('document', 'viewer', 'team#member', 'share', ARRAY['view']::text[], 'share document.viewer team#member');

DO $w$
DECLARE n bigint;
BEGIN
  SELECT count(*) INTO n FROM authz.shares g WHERE g.relation NOT LIKE 'role:%' AND NOT EXISTS (
    SELECT 1 FROM authz_int.shared_relations s WHERE s.object_type = g.object_type AND s.relation = g.relation
      AND s.subject = CASE WHEN g.subject_type IN ('anyone', 'link') THEN g.subject_type
                           WHEN g.subject_id = '*' AND g.subject_relation = '' THEN g.subject_type || ':*'
                           WHEN g.subject_relation <> '' THEN g.subject_type || '#' || g.subject_relation
                           ELSE g.subject_type END);
  IF n > 0 THEN
    RAISE WARNING '% shares are for relations this policy does not declare as shared; they are kept, but grant nothing', n;
  END IF;
END $w$;

CREATE TABLE authz_int.role_subjects (object_type text, subject text, PRIMARY KEY (object_type, subject));

CREATE TABLE authz_int.role_grantable (object_type text, permission text, PRIMARY KEY (object_type, permission));

CREATE TABLE authz_int.caveats (name text PRIMARY KEY);

-- per-type indexes on share ids, for lookups by object
DO $gi$
DECLARE i record;
BEGIN
  FOR i IN SELECT c.relname FROM pg_index x JOIN pg_class c ON c.oid = x.indexrelid
           WHERE x.indrelid = 'authz.shares'::regclass AND (c.relname LIKE 'shares\_obj\_%' OR c.relname LIKE 'grants\_obj\_%')
             AND c.relname <> ALL (ARRAY['shares_obj_user_bigint', 'shares_obj_team_bigint', 'shares_obj_document_bigint']::text[]) LOOP
    EXECUTE format('DROP INDEX authz.%I', i.relname);
  END LOOP;
END $gi$;
CREATE INDEX IF NOT EXISTS "shares_obj_user_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'user';
CREATE INDEX IF NOT EXISTS "shares_obj_team_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'team';
CREATE INDEX IF NOT EXISTS "shares_obj_document_bigint" ON authz.shares ((object_id::bigint), relation) WHERE object_type = 'document';

-- Scopes: what a token may do (policy 'scope' lines; 'read' is built in unless redefined)
CREATE TABLE authz_int.scope_items (scope text, kind text, qual text, word text);
INSERT INTO authz_int.scope_items VALUES
  ('read', 'cmd', NULL, 'select'),
  ('read', 'perm', NULL, '*');

-- the scopes this transaction is limited to (NULL: not limited); believed only if signed, like the user
CREATE FUNCTION authz_int.scopes_active() RETURNS text[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT CASE WHEN NOT authz_int.session_ok() THEN ARRAY[]::text[]
              WHEN coalesce(current_setting('authz.scopes', true), '') = '' THEN NULL
              ELSE ARRAY(SELECT btrim(x) FROM unnest(string_to_array(current_setting('authz.scopes', true), ',')) x
                         WHERE btrim(x) <> '') END $f$;
-- may this transaction run a command on a table?
CREATE FUNCTION authz_int.scope_cmd(p_table text, p_cmd text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'cmd'
                              AND i.word = p_cmd AND (i.qual IS NULL OR i.qual = p_table))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
-- may this transaction ask about (or use) a permission?
CREATE FUNCTION authz_int.scope_perm(p_type text, p_perm text) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'perm'
                              AND (i.word = p_perm OR i.word = '*') AND (i.qual IS NULL OR i.qual = p_type))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
-- may this transaction change anything? (not while viewing as someone, not with read-only scopes)
CREATE FUNCTION authz_int.writable() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce(current_setting('authz.acting_user', true), '') = ''
     AND (s IS NULL OR EXISTS (SELECT 1 FROM authz_int.scope_items i WHERE i.scope = ANY (s) AND i.kind = 'cmd'
                               AND i.word <> 'select'))
  FROM (SELECT authz_int.scopes_active() AS s) x $f$;
CREATE FUNCTION authz_int.check_writable() RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT authz_int.writable() THEN
    RAISE EXCEPTION 'this session is read-only (viewing as someone else, or a read-only token)'
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
END $f$;
-- the role that called (inside SECURITY DEFINER functions current_user is the owner)
CREATE FUNCTION authz_int.caller_role() RETURNS text
LANGUAGE sql STABLE AS $f$
  SELECT CASE WHEN current_setting('role') = 'none' THEN session_user::text ELSE current_setting('role') END $f$;
-- The caller is an administrator, not the app: a superuser, BYPASSRLS, or the policy's owner (or a member of it)
CREATE FUNCTION authz_int.caller_is_admin() RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce((SELECT r.rolsuper OR r.rolbypassrls OR pg_has_role(r.oid, n.nspowner, 'MEMBER')
                   FROM pg_roles r, pg_namespace n
                   WHERE r.rolname = authz_int.caller_role() AND n.nspname = 'authz_int'), false) $f$;
-- one row in the audit trail
CREATE FUNCTION authz_int.audit(p_action text, p_object_type text, p_object_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text, p_detail jsonb) RETURNS void
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  INSERT INTO authz.audit (db_role, user_id, acting_user, action, object_type, object_id, relation,
                           subject_type, subject_id, subject_relation, detail, reason)
  VALUES (authz_int.caller_role(), authz_int.actor(),
          nullif(current_setting('authz.acting_user', true), ''), p_action, p_object_type, p_object_id, p_relation,
          p_subject_type, p_subject_id, p_subject_relation, p_detail,
          nullif(current_setting('authz_ctx.reason', true), '')) $f$;

-- The change feed: objects whose access may have changed. Consumers poll authz.changes_since(pos).
-- NOTIFY on channel authz_changes only with INSERT INTO authz.settings VALUES ('notify_changes', 'on'):
-- Postgres commits notifying transactions one at a time, so it would queue every write.
CREATE FUNCTION authz_int.changed(p_type text, p_ids text[], p_cause text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_pos bigint;
BEGIN
  IF coalesce(cardinality(p_ids), 0) = 0 THEN RETURN; END IF;
  INSERT INTO authz.changes (object_type, object_ids, cause) VALUES (p_type, p_ids, p_cause) RETURNING pos INTO v_pos;
  IF (SELECT s.value FROM authz.settings s WHERE s.key = 'notify_changes') = 'on' THEN
    PERFORM pg_notify('authz_changes', v_pos::text);
  END IF;
END $f$;
-- Read the feed from a position: SELECT * FROM authz.changes_since(0)  (administrators, sync jobs).
-- A reader behind what authz.trim_changes() removed gets an error: it must read everything again.
CREATE OR REPLACE FUNCTION authz.changes_since(p_pos bigint, p_limit int DEFAULT 1000) RETURNS SETOF authz.changes
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_to bigint := (SELECT s.value::bigint FROM authz.settings s WHERE s.key = 'changes_trimmed_to');
BEGIN
  IF p_pos < v_to THEN
    RAISE EXCEPTION 'the change feed up to position % was trimmed: read everything again, then follow from there', v_to
      USING ERRCODE = 'object_not_in_prerequisite_state', HINT = 'rowstile help AZ712';
  END IF;
  RETURN QUERY SELECT * FROM authz.changes WHERE pos > p_pos ORDER BY pos LIMIT p_limit;
END $f$;

-- Retention (both grow forever otherwise); schedule these, with pg_cron or the app's jobs.
-- The feed: entries older than p_keep, by default the setting changes_keep, else 7 days.
CREATE OR REPLACE FUNCTION authz.trim_changes(p_keep interval DEFAULT NULL) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE
  v_keep interval := coalesce(p_keep, (SELECT s.value::interval FROM authz.settings s WHERE s.key = 'changes_keep'),
                              interval '7 days');
  v_to bigint; n bigint;
BEGIN
  SELECT max(c.pos) INTO v_to FROM authz.changes c WHERE c.at < now() - v_keep;
  IF v_to IS NULL THEN RETURN 0; END IF;
  DELETE FROM authz.changes c WHERE c.pos <= v_to;
  GET DIAGNOSTICS n = ROW_COUNT;
  INSERT INTO authz.settings VALUES ('changes_trimmed_to', v_to::text)
    ON CONFLICT (key) DO UPDATE SET value = greatest(authz.settings.value::bigint, v_to)::text;
  RETURN n;
END $f$;
-- The audit trail: entries older than p_keep (no default: how long to keep it is a compliance
-- decision). The trim itself is recorded in the audit trail.
CREATE OR REPLACE FUNCTION authz.trim_audit(p_keep interval) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_before timestamptz; n bigint;
BEGIN
  IF p_keep IS NULL OR p_keep < interval '0' THEN
    RAISE EXCEPTION 'say how long to keep the audit trail, e.g. authz.trim_audit(interval ''2 years'')' USING HINT = 'rowstile help AZ710';
  END IF;
  v_before := now() - p_keep;
  -- the one way past the trigger is DDL, as the owner, here: nothing a session can set lets a DELETE through
  -- (ALTER TABLE takes an exclusive lock on the trail until the transaction ends)
  ALTER TABLE authz.audit DISABLE TRIGGER authz_audit_append_only;
  DELETE FROM authz.audit a WHERE a.at < v_before;
  GET DIAGNOSTICS n = ROW_COUNT;
  ALTER TABLE authz.audit ENABLE TRIGGER authz_audit_append_only;
  INSERT INTO authz.audit (db_role, user_id, action, detail)
  VALUES (authz_int.caller_role(), authz_int.actor(), 'trim_audit',
          jsonb_build_object('before', v_before, 'rows', n));
  RETURN n;
END $f$;

-- The audit trail only grows, except through authz.trim_audit()
CREATE FUNCTION authz_int.audit_is_append_only() RETURNS trigger
LANGUAGE plpgsql AS $f$
BEGIN
  RAISE EXCEPTION 'the audit trail cannot be changed' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ711';
END $f$;
CREATE TRIGGER authz_audit_append_only BEFORE UPDATE OR DELETE ON authz.audit
  FOR EACH ROW EXECUTE FUNCTION authz_int.audit_is_append_only();
CREATE TRIGGER authz_audit_no_truncate BEFORE TRUNCATE ON authz.audit
  FOR EACH STATEMENT EXECUTE FUNCTION authz_int.audit_is_append_only();

-- shares and role assignments
CREATE FUNCTION authz_int.on_grant() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r authz.shares;
BEGIN
  r := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  PERFORM authz_int.audit(CASE TG_OP WHEN 'INSERT' THEN 'share' WHEN 'DELETE' THEN 'unshare' ELSE 'share_changed' END,
    r.object_type, r.object_id, r.relation, r.subject_type,
    CASE WHEN r.subject_type = 'link' THEN '(link)' ELSE r.subject_id END, r.subject_relation,
    jsonb_strip_nulls(jsonb_build_object('expires_at', r.expires_at, 'starts_at', r.starts_at, 'caveat', r.caveat,
                                         'created_by', r.created_by)));
  PERFORM authz_int.changed(r.object_type, ARRAY[r.object_id], 'share');
  IF TG_OP = 'UPDATE' AND OLD.object_id <> NEW.object_id THEN
    PERFORM authz_int.changed(OLD.object_type, ARRAY[OLD.object_id], 'share');
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_grant_audit AFTER INSERT OR UPDATE OR DELETE ON authz.shares
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_grant();
CREATE FUNCTION authz_int.on_role() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF TG_TABLE_NAME = 'roles' THEN
    PERFORM authz_int.audit(lower(TG_OP) || '_role', CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_type ELSE NEW.owner_type END,
      CASE WHEN TG_OP = 'DELETE' THEN OLD.owner_id ELSE NEW.owner_id END, NULL, NULL, NULL, NULL,
      to_jsonb(CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END));
  ELSE
    PERFORM authz_int.audit(CASE TG_OP WHEN 'DELETE' THEN 'role_permission_removed' ELSE 'role_permission_added' END,
      NULL, NULL, 'role:' || CASE WHEN TG_OP = 'DELETE' THEN OLD.role_id ELSE NEW.role_id END, NULL, NULL, NULL,
      jsonb_build_object('permission', CASE WHEN TG_OP = 'DELETE' THEN OLD.permission ELSE NEW.permission END));
  END IF;
  RETURN NULL;
END $f$;
CREATE TRIGGER authz_role_audit AFTER INSERT OR UPDATE OR DELETE ON authz.roles
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_role();
CREATE TRIGGER authz_role_perm_audit AFTER INSERT OR DELETE ON authz.role_permissions
  FOR EACH ROW EXECUTE FUNCTION authz_int.on_role();

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', 'applying the policy: the row was deleted', true); END $r$;

-- Shares stored with ids that aren't canonical ('007', an uppercase uuid: written directly before every
-- write went through authz_int.canon) are made canonical, since the sweep below and the triggers compare
-- text; one that then repeats a share already stored goes, the first made staying
CREATE TEMP TABLE authz_uncanonical ON COMMIT DROP AS
  SELECT g.ctid AS row, authz_int.canon(g.object_type, g.object_id) AS object_id,
         authz_int.canon(g.subject_type, g.subject_id) AS subject_id
  FROM authz.shares g
  WHERE g.object_id IS DISTINCT FROM authz_int.canon(g.object_type, g.object_id)
     OR g.subject_id IS DISTINCT FROM authz_int.canon(g.subject_type, g.subject_id);
DELETE FROM authz.shares g USING authz_uncanonical u
WHERE g.ctid = u.row AND EXISTS (
  SELECT 1 FROM authz.shares c WHERE c.object_type = g.object_type AND c.object_id = u.object_id AND c.relation = g.relation
    AND c.subject_type = g.subject_type AND c.subject_id = u.subject_id AND c.subject_relation = g.subject_relation);
DELETE FROM authz.shares g USING (
  SELECT u.row, row_number() OVER (PARTITION BY s.object_type, u.object_id, s.relation, s.subject_type, u.subject_id,
                                   s.subject_relation ORDER BY s.created_at, u.row) AS n
  FROM authz_uncanonical u JOIN authz.shares s ON s.ctid = u.row) d
WHERE g.ctid = d.row AND d.n > 1;
UPDATE authz.shares g SET object_id = u.object_id, subject_id = u.subject_id FROM authz_uncanonical u WHERE g.ctid = u.row;
DROP TABLE authz_uncanonical;

-- Shares on rows that no longer exist (deleted while no trigger watched them) are dropped
DELETE FROM authz.shares g WHERE g.object_type = 'user' AND NOT EXISTS (SELECT 1 FROM "app"."users" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'user' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "app"."users" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'team' AND NOT EXISTS (SELECT 1 FROM "app"."teams" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'team' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "app"."teams" x WHERE x."id"::text = g.subject_id);
DELETE FROM authz.shares g WHERE g.object_type = 'document' AND NOT EXISTS (SELECT 1 FROM "app"."documents" x WHERE x."id"::text = g.object_id);
DELETE FROM authz.shares g WHERE g.subject_type = 'document' AND g.subject_id <> '*' AND NOT EXISTS (SELECT 1 FROM "app"."documents" x WHERE x."id"::text = g.subject_id);

DO $r$ BEGIN PERFORM set_config('authz_ctx.reason', '', true); END $r$;

-- 'shared if {...}' conditions (they run as the policy's owner, like permissions)
CREATE FUNCTION authz_int.share_if(p_key text, p_object_id text, p_subject_type text, p_subject_id text,
  p_subject_relation text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  CASE p_key
    WHEN NULL THEN NULL;
    ELSE RETURN true;
  END CASE;
END $f$;

-- `roles : ... from rel`: a role counts on an object only if what rel links the object to owns it
CREATE FUNCTION authz_int.role_owned(p_type text, p_id text, p_owner_type text, p_owner_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  CASE p_type
    WHEN NULL THEN NULL;
    ELSE RETURN true;
  END CASE;
END $f$;
-- the type that owns the custom roles of an object type, when the policy says (from rel)
CREATE FUNCTION authz_int.role_owner_type(p_object_type text) RETURNS text
LANGUAGE plpgsql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  CASE p_object_type
    WHEN NULL THEN NULL;
    ELSE RETURN NULL;
  END CASE;
END $f$;
-- relations ('role:<id>') of the custom roles that include a permission
CREATE FUNCTION authz_int.role_relations(p_type text, p_perm text) RETURNS text[]
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT coalesce(array_agg('role:' || r.id), '{}') FROM authz.roles r
  JOIN authz.role_permissions p ON p.role_id = r.id
  WHERE r.object_type = p_type AND p.permission = p_perm $f$;
-- deleting a role removes its assignments
CREATE FUNCTION authz_int.role_gone() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
