DO $tr$ BEGIN
  IF (SELECT relkind FROM pg_class WHERE oid = '"app"."team_members"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_rel_audit_1_ins" AFTER INSERT ON "app"."team_members" REFERENCING NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."rel_audit_1_ins"()';
