  IF (SELECT relkind FROM pg_class WHERE oid = '"app"."team_members"'::regclass) IN ('r', 'p') THEN
    EXECUTE 'CREATE TRIGGER "authz_rel_audit_1_upd" AFTER UPDATE ON "app"."team_members" REFERENCING OLD TABLE AS old_rows NEW TABLE AS new_rows FOR EACH STATEMENT EXECUTE FUNCTION authz_int."rel_audit_1_upd"()';
