    EXECUTE 'CREATE TRIGGER "authz_document_col_audit_row" AFTER UPDATE ON "app"."documents" FOR EACH ROW WHEN (OLD."owner_id" IS DISTINCT FROM NEW."owner_id") EXECUTE FUNCTION authz_int."document__col_audit_row"()';
