-- document.share (line 15): owner
CREATE VIEW authz_int."document__share" AS
  SELECT id FROM authz_int."document__owner";
CREATE VIEW authz_gen."document__share" WITH (security_barrier) AS SELECT id FROM authz_int."document__share";

-- team.member (line 8)
CREATE VIEW authz_int."team__member" AS
  SELECT s."team_id" AS id FROM "app"."team_members" s WHERE s."user_id" = (SELECT authz.uid());
