-- document.editor (line 12)
CREATE VIEW authz_int."document__editor" AS
  (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'editor' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL)
  UNION ALL
  (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'editor' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL);
CREATE VIEW authz_gen."document__editor" WITH (security_barrier) AS SELECT id FROM authz_int."document__editor";

-- document.edit (line 16): share or editor
CREATE VIEW authz_int."document__edit" AS
  (SELECT id FROM authz_int."document__owner")
  UNION ALL
  (SELECT id FROM authz_int."document__editor");
CREATE VIEW authz_gen."document__edit" WITH (security_barrier) AS SELECT id FROM authz_int."document__edit";

-- document.viewer (line 13)
CREATE VIEW authz_int."document__viewer" AS
  (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL)
  UNION ALL
  (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'viewer' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL);
CREATE VIEW authz_gen."document__viewer" WITH (security_barrier) AS SELECT id FROM authz_int."document__viewer";

-- document.view (line 17): edit or viewer
CREATE VIEW authz_int."document__view" AS
  (SELECT id FROM authz_int."document__owner")
  UNION ALL
  (SELECT id FROM authz_int."document__editor")
  UNION ALL
  (SELECT id FROM authz_int."document__viewer");
CREATE VIEW authz_gen."document__view" WITH (security_barrier) AS SELECT id FROM authz_int."document__view";

ALTER TABLE "app"."documents" ENABLE ROW LEVEL SECURITY;
-- its partitions and the tables that inherit from it: row-level security on, with no policies of their own,
-- so they are read and written through it only (read directly, they would skip its rules and triggers)
DO $rls$
DECLARE c regclass;
BEGIN
  FOR c IN WITH RECURSIVE d(oid) AS (
             SELECT i.inhrelid FROM pg_catalog.pg_inherits i WHERE i.inhparent = '"app"."documents"'::regclass
             UNION SELECT i.inhrelid FROM pg_catalog.pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass FROM d JOIN pg_catalog.pg_class k ON k.oid = d.oid WHERE NOT k.relrowsecurity LOOP
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', c);
  END LOOP;
END $rls$;

CREATE FUNCTION authz_gen."app.documents:insert:items"(p_row "app"."documents") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT ARRAY[
    coalesce(coalesce("documents"."owner_id" = (SELECT authz.uid()), false), false),
    coalesce((SELECT authz_int.scope_cmd('app.documents', 'insert')), false),
    coalesce(true, false),
    coalesce(coalesce("documents"."owner_id" = (SELECT authz.uid()), false), false)]
  FROM (SELECT (p_row).*) AS "documents";
END;

CREATE FUNCTION authz_gen."app.documents:insert:why"(p_row "app"."documents") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."app.documents:insert:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'insert : owner  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule app.documents insert'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow insert on app.documents'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'owner';
END $f$;

CREATE FUNCTION authz_gen."app.documents:insert:refuse"(p_row "app"."documents") RETURNS boolean
LANGUAGE plpgsql VOLATILE SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_who text := CASE WHEN coalesce(current_setting('authz.user_id', true), '') = '' THEN 'someone not signed in'
  ELSE coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || current_setting('authz.user_id', true) END;
BEGIN
  BEGIN
    v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."app.documents:insert:why"(p_row) l);
  EXCEPTION WHEN OTHERS THEN
    v_lines := 'no explanation: ' || SQLERRM;
  END;
  RAISE EXCEPTION USING ERRCODE = 'insufficient_privilege', MESSAGE = 'permission denied: ' || v_who || ' may not ' || 'insert this row into app.documents',
    DETAIL = v_lines, SCHEMA = 'app', TABLE = 'documents', CONSTRAINT = 'authz_insert',
    HINT = 'rowstile help AZ709';
END $f$;

CREATE FUNCTION authz_gen."app.documents:update:items"(p_row "app"."documents") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT ARRAY[
    coalesce((coalesce("documents"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = "documents"."id")), false),
    coalesce((SELECT authz_int.scope_cmd('app.documents', 'update')), false),
    coalesce(true, false),
    coalesce((coalesce("documents"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = "documents"."id")), false)]
  FROM (SELECT (p_row).*) AS "documents";
END;

CREATE FUNCTION authz_gen."app.documents:update:why"(p_row "app"."documents") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."app.documents:update:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update : edit  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule app.documents update'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow update on app.documents'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'edit';
  IF NOT v[4] THEN
    RETURN QUERY SELECT '    ' || l FROM authz.explain('document', ((p_row)."id"::text), 'edit') l LIMIT 20;
  END IF;
END $f$;

CREATE FUNCTION authz_gen."app.documents:update:refuse"(p_row "app"."documents") RETURNS boolean
LANGUAGE plpgsql VOLATILE SET search_path FROM CURRENT AS $f$
DECLARE v_lines text; v_who text := CASE WHEN coalesce(current_setting('authz.user_id', true), '') = '' THEN 'someone not signed in'
  ELSE coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || current_setting('authz.user_id', true) END;
BEGIN
  BEGIN
    v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."app.documents:update:why"(p_row) l);
  EXCEPTION WHEN OTHERS THEN
    v_lines := 'no explanation: ' || SQLERRM;
  END;
  RAISE EXCEPTION USING ERRCODE = 'insufficient_privilege', MESSAGE = 'permission denied: ' || v_who || ' may not ' || 'update this row of app.documents to these values',
    DETAIL = v_lines, SCHEMA = 'app', TABLE = 'documents', CONSTRAINT = 'authz_update',
    HINT = 'the update rule must hold on the row after the change too (Postgres checks both) (rowstile help AZ709)';
END $f$;

CREATE FUNCTION authz_gen."app.documents:delete:items"(p_row "app"."documents") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT ARRAY[
    coalesce(coalesce("documents"."owner_id" = (SELECT authz.uid()), false), false),
    coalesce((SELECT authz_int.scope_cmd('app.documents', 'delete')), false),
    coalesce(true, false),
    coalesce(coalesce("documents"."owner_id" = (SELECT authz.uid()), false), false)]
  FROM (SELECT (p_row).*) AS "documents";
END;

CREATE FUNCTION authz_gen."app.documents:delete:why"(p_row "app"."documents") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."app.documents:delete:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'delete : share  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule app.documents delete'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow delete on app.documents'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'share';
  IF NOT v[4] THEN
    RETURN QUERY SELECT '    ' || l FROM authz.explain('document', ((p_row)."id"::text), 'share') l LIMIT 20;
  END IF;
END $f$;

CREATE FUNCTION authz_gen."app.documents:rules:explain"(p_command text, p_id text, p_row jsonb) RETURNS text[]
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
DECLARE r_old "app"."documents"; r_new "app"."documents";
BEGIN
  IF p_command = 'insert' THEN
    RETURN ARRAY(SELECT * FROM authz_gen."app.documents:insert:why"(jsonb_populate_record(NULL::"app"."documents", coalesce(p_row, '{}'))));
  END IF;
  IF p_id IS NULL THEN
    RAISE EXCEPTION 'which row? authz.explain_rule(%, %, id)', 'app.documents', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  SELECT x.* INTO r_old FROM "app"."documents" x WHERE x."id" = p_id::bigint;
  IF NOT FOUND THEN
    RETURN NULL;          -- not there, or the signed-in user can't see it
  END IF;
  IF p_command = 'delete' THEN
    RETURN ARRAY(SELECT * FROM authz_gen."app.documents:delete:why"(r_old));
  END IF;
  r_new := jsonb_populate_record(r_old, coalesce(p_row, '{}'));
  RETURN ARRAY(SELECT * FROM authz_gen."app.documents:update:why"(r_old)) || CASE WHEN p_row IS NULL THEN '{}'::text[] ELSE ARRAY['after the change:'] || ARRAY(SELECT '  ' || l FROM authz_gen."app.documents:update:why"(r_new) l) END;
END $f$;

-- app.documents select (line 20): view
CREATE POLICY "authz_select" ON "app"."documents" FOR SELECT TO starter_app
  USING (((SELECT authz_int.scope_cmd('app.documents', 'select')) AND (coalesce("documents"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = "documents"."id")
    OR EXISTS (SELECT 1 FROM authz_gen."document__viewer" v WHERE v.id = "documents"."id"))));

COMMENT ON POLICY "authz_select" ON "app"."documents" IS 'rowstile';

-- app.documents insert (line 21): owner
CREATE POLICY "authz_insert" ON "app"."documents" FOR INSERT TO starter_app
  WITH CHECK (((SELECT authz_int.scope_cmd('app.documents', 'insert')) AND coalesce("documents"."owner_id" = (SELECT authz.uid()), false))
    OR authz_gen."app.documents:insert:refuse"(ROW("documents".*)::"app"."documents"));

COMMENT ON POLICY "authz_insert" ON "app"."documents" IS 'rowstile';

-- app.documents update (line 22): edit
CREATE POLICY "authz_update" ON "app"."documents" FOR UPDATE TO starter_app
  USING (((SELECT authz_int.scope_cmd('app.documents', 'update')) AND (coalesce("documents"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = "documents"."id"))))
  WITH CHECK (((SELECT authz_int.scope_cmd('app.documents', 'update')) AND (coalesce("documents"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = "documents"."id")))
    OR authz_gen."app.documents:update:refuse"(ROW("documents".*)::"app"."documents"));

COMMENT ON POLICY "authz_update" ON "app"."documents" IS 'rowstile';

-- app.documents delete (line 24): share
CREATE POLICY "authz_delete" ON "app"."documents" FOR DELETE TO starter_app
  USING (((SELECT authz_int.scope_cmd('app.documents', 'delete')) AND coalesce("documents"."owner_id" = (SELECT authz.uid()), false)));

COMMENT ON POLICY "authz_delete" ON "app"."documents" IS 'rowstile';

CREATE FUNCTION authz_gen."app.documents:column_1:items"(p_row "app"."documents") RETURNS boolean[]
LANGUAGE sql STABLE
BEGIN ATOMIC
  SELECT ARRAY[
    coalesce(coalesce((false), false), false),
    coalesce((SELECT authz_int.scope_cmd('app.documents', 'update')), false),
    coalesce(true, false),
    coalesce(coalesce((false), false), false)]
  FROM (SELECT (p_row).*) AS "documents";
END;

CREATE FUNCTION authz_gen."app.documents:column_1:why"(p_row "app"."documents") RETURNS SETOF text
LANGUAGE plpgsql STABLE SET search_path FROM CURRENT AS $f$
#variable_conflict use_column
DECLARE v boolean[] := authz_gen."app.documents:column_1:items"(p_row); v_t record;
BEGIN
  RETURN NEXT CASE WHEN v[1] THEN 'yes  ' ELSE 'no   ' END || 'update owner_id : nobody  (' || coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = 'rule app.documents update owner_id'), '?') || ')';
  IF NOT v[2] THEN RETURN NEXT '  no   the sign-in''s scopes do not allow update on app.documents'; END IF;
  RETURN NEXT CASE WHEN v[4] THEN '  yes  ' ELSE '  no   ' END || 'nobody';
END $f$;

-- app.documents update owner_id (line 23): nobody
-- checked on the row before the change, for roles that row-level security applies to
CREATE FUNCTION authz_int."document__update_1"() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $f$
DECLARE v_lines text;
BEGIN
  IF pg_catalog.row_security_active(TG_RELID)
     AND NOT coalesce((SELECT coalesce((false), false) FROM (SELECT OLD.*) AS "documents"), false) THEN
    BEGIN
      v_lines := (SELECT string_agg(l, E'\n') FROM authz_gen."app.documents:column_1:why"(OLD) l);
    EXCEPTION WHEN OTHERS THEN
      v_lines := 'no explanation: ' || SQLERRM;
    END;
    RAISE EXCEPTION 'changing owner_id of app.documents % needs: nobody', OLD."id" USING ERRCODE = 'insufficient_privilege', DETAIL = v_lines,
      SCHEMA = 'app', TABLE = 'documents', CONSTRAINT = 'authz_update', HINT = 'rowstile help AZ709';
  END IF;
  RETURN NEW;
END $f$;
CREATE TRIGGER "authz_update_1" BEFORE UPDATE ON "app"."documents" FOR EACH ROW
  WHEN (OLD."owner_id" IS DISTINCT FROM NEW."owner_id")
  EXECUTE FUNCTION authz_int."document__update_1"();

-- Foreign keys that delete governed rows skip row-level security
DO $fk$
DECLARE c record;
BEGIN
  FOR c IN SELECT con.conname, con.conrelid::regclass AS child, con.confrelid::regclass AS parent
           FROM pg_constraint con
           WHERE con.contype = 'f' AND con.confdeltype = 'c' AND con.conrelid IN ('"app"."documents"'::regclass) LOOP
    RAISE WARNING 'foreign key % on % is ON DELETE CASCADE: deleting a row of % also deletes rows of %, and cascades skip row-level security, so a user could remove rows they cannot see. Use ON DELETE RESTRICT unless that is intended.',
      c.conname, c.child, c.parent, c.child;
  END LOOP;
END $fk$;

-- Column privileges: masked columns are read through the masked view only
DO $mc$
DECLARE r record; cols text;
BEGIN
  -- tables that are no longer masked get back the table-wide SELECT they had
  FOR r IN SELECT * FROM authz.masked_tables WHERE (tbl || '|' || role) <> ALL (ARRAY[]::text[]) LOOP
    IF to_regclass(r.tbl) IS NOT NULL AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r.role) THEN
      EXECUTE format('GRANT SELECT ON %s TO %I', r.tbl, r.role);
    END IF;
    DELETE FROM authz.masked_tables WHERE tbl = r.tbl AND role = r.role;
  END LOOP;

END $mc$;

CREATE TABLE authz_int.masked_columns (tbl text, col text, view text, PRIMARY KEY (tbl, col));

-- Check a permission from app code: SELECT authz.can('file', 11, 'edit')
-- (only objects that exist; plans are cached per session)
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id text, p_perm text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE v_allowed boolean; v_bigint bigint;
BEGIN
  IF current_setting('authz_debug.log_decisions', true) = 'on'
     AND current_setting('authz_debug.logging', true) IS DISTINCT FROM 'on' THEN
    -- decision log (SET authz_debug.log_decisions = on; lines go to the server log)
    PERFORM set_config('authz_debug.logging', 'on', true);
    v_allowed := authz.can(p_type, p_id, p_perm);
    PERFORM set_config('authz_debug.logging', 'off', true);
    RAISE LOG 'authz decision: user=% type=% id=% perm=% -> %',
      coalesce(to_json(nullif(current_setting('authz.user_id', true), ''))::text, 'none'), to_json(p_type)::text,
      to_json(p_id)::text, to_json(p_perm)::text, coalesce(v_allowed::text, 'error');
    RETURN v_allowed;
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN false; END IF;
  CASE p_type
    WHEN 'document' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN false; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN RETURN coalesce((SELECT coalesce(o."owner_id" = (SELECT authz.uid()), false) FROM "app"."documents" o WHERE o."id" = v_bigint), false);
        WHEN 'edit' THEN RETURN coalesce((SELECT (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = o."id")) FROM "app"."documents" o WHERE o."id" = v_bigint), false);
        WHEN 'view' THEN RETURN coalesce((SELECT (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."document__viewer" v WHERE v.id = o."id")) FROM "app"."documents" o WHERE o."id" = v_bigint), false);
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Everything the user holds a permission on: SELECT * FROM authz.list('folder', 'edit')
-- In pages, in key order: authz.list('file', 'view', NULL, 1000), then the last id seen as p_after
CREATE OR REPLACE FUNCTION authz.list(p_type text, p_perm text, p_after text DEFAULT NULL, p_limit int DEFAULT NULL)
RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  -- a page cursor or size from a request: the caller's mistake, said plainly (the queries below would cast it)
  IF p_limit < 0 THEN
    RAISE EXCEPTION 'the page size must not be negative (got %)', p_limit
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF p_after IS NOT NULL AND NOT coalesce(pg_catalog.pg_input_is_valid(p_after,
                                            (SELECT keytype FROM authz_int.types WHERE name = p_type)), true) THEN
    RAISE EXCEPTION 'the page cursor % is not a % id', quote_literal(left(p_after, 40)), p_type
      USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  IF NOT authz_int.scope_perm(p_type, p_perm) THEN RETURN; END IF;
  CASE p_type || '.' || p_perm
    WHEN 'document.share' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."documents" o
        WHERE coalesce(o."owner_id" = (SELECT authz.uid()), false);
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."documents" o
        WHERE coalesce(o."owner_id" = (SELECT authz.uid()), false)
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."documents" o
        WHERE o."id" > p_after::bigint AND coalesce(o."owner_id" = (SELECT authz.uid()), false)
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'document.edit' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."documents" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."documents" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."documents" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    WHEN 'document.view' THEN
      IF p_limit IS NULL AND p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."documents" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."document__viewer" v WHERE v.id = o."id"));
      ELSIF p_after IS NULL THEN
        RETURN QUERY SELECT o."id"::text FROM "app"."documents" o
        WHERE (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."document__viewer" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      ELSE
        RETURN QUERY SELECT o."id"::text FROM "app"."documents" o
        WHERE o."id" > p_after::bigint AND (coalesce(o."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = o."id")
    OR EXISTS (SELECT 1 FROM authz_gen."document__viewer" v WHERE v.id = o."id"))
        ORDER BY o."id" LIMIT p_limit;
      END IF;
    ELSE
      RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Every permission the user holds on one object: SELECT authz.perms('file', 11)
CREATE OR REPLACE FUNCTION authz.perms(p_type text, p_id text) RETURNS text[]
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE names text[];
BEGIN
  CASE p_type
    WHEN 'document' THEN names := ARRAY['share', 'edit', 'view']::text[];
    ELSE RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  RETURN ARRAY(SELECT n FROM unnest(names) n WHERE authz.can(p_type, p_id, n));
END $f$;

-- The permissions the user holds on many objects, in one call (a list's buttons): SELECT * FROM authz.perms_of('folder', ARRAY['1', '2'])
CREATE OR REPLACE FUNCTION authz.perms_of(p_type text, p_ids text[]) RETURNS TABLE (id text, perms text[])
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  RETURN QUERY SELECT x, authz.perms(p_type, x) FROM unnest(p_ids) WITH ORDINALITY u(x, n) ORDER BY n;
END $f$;
CREATE OR REPLACE FUNCTION authz.can(p_type text, p_id bigint, p_perm text) RETURNS boolean LANGUAGE sql STABLE AS
  $$ SELECT authz.can(p_type, p_id::text, p_perm) $$;
CREATE OR REPLACE FUNCTION authz.perms(p_type text, p_id bigint) RETURNS text[] LANGUAGE sql STABLE AS
  $$ SELECT authz.perms(p_type, p_id::text) $$;

-- Share: needs the relation's 'shared by' permission on the object, and every permission
-- the relation grants (you can't grant more than you hold); the subject must exist
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '',
  p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_tbl text; v_find text; v_found boolean; v_key text; v_rel authz_int.shared_relations; v_need text;
        v_role authz.roles;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- lock the object (FOR KEY SHARE): a concurrent delete waits for us, or we for it
  SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_type;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707'; END IF;
  IF NOT pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find) INTO v_found USING p_id;
  -- a caller who may share nothing on the object gets the answer a missing object gets (this same RAISE),
  -- before the subject and the relation are looked at: sharing never tells a hidden object from a missing one
  v_found := v_found AND EXISTS (
    SELECT 1 FROM (SELECT s.shared_by AS perm FROM authz_int.shared_relations s WHERE s.object_type = p_type
                   UNION SELECT 'share') x
    -- (CASE: authz.can raises for a permission the type doesn't have, and AND doesn't say which runs first)
    WHERE CASE WHEN EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = x.perm)
               THEN authz.can(p_type, p_id, x.perm) ELSE false END);
  IF NOT v_found THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  v_key := CASE WHEN p_subject_type IN ('anyone', 'link') THEN p_subject_type
                WHEN p_subject_id = '*' AND p_subject_relation = '' THEN p_subject_type || ':*'
                WHEN p_subject_relation <> '' THEN p_subject_type || '#' || p_subject_relation
                ELSE p_subject_type END;
  -- the subject must exist (and is locked, like the object)
  IF v_key NOT LIKE '%:*' AND v_key NOT IN ('anyone', 'link') THEN
    SELECT t.tbl, t.find INTO v_tbl, v_find FROM authz_int.types t WHERE t.name = p_subject_type;
    v_found := v_tbl IS NOT NULL AND pg_catalog.pg_input_is_valid(p_subject_id,
                 (SELECT keytype FROM authz_int.types WHERE name = p_subject_type));
    IF v_found THEN
      EXECUTE format('SELECT EXISTS (SELECT 1 FROM %s x WHERE %s FOR KEY SHARE)', v_tbl, v_find)
        INTO v_found USING p_subject_id;
    END IF;
    IF NOT v_found THEN
      RAISE EXCEPTION 'there is no % %', p_subject_type, p_subject_id USING ERRCODE = 'foreign_key_violation', HINT = 'rowstile help AZ708';
    END IF;
  END IF;
  IF p_relation LIKE 'role:%' THEN
    -- a custom role: its type must match, the subject must be allowed, and you must hold all it grants
    SELECT * INTO v_role FROM authz.roles WHERE 'role:' || id = p_relation;
    IF v_role.id IS NULL OR v_role.object_type <> p_type THEN
      RAISE EXCEPTION 'no role % for %', p_relation, p_type USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT authz_int.role_owned(p_type, p_id, v_role.owner_type, v_role.owner_id) THEN
      RAISE EXCEPTION 'role % belongs to % %, which doesn''t own % %', v_role.name, v_role.owner_type, v_role.owner_id,
        p_type, p_id USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.role_subjects WHERE object_type = p_type AND subject = v_key) THEN
      RAISE EXCEPTION 'custom roles on % cannot be given to %', p_type, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'share')
       OR NOT authz.can(p_type, p_id, 'share') THEN
      RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(permission, ', ') INTO v_need FROM authz.role_permissions
    WHERE role_id = v_role.id AND NOT authz.can(p_type, p_id, permission);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot give role % on % %: you do not hold %', v_role.name, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
  ELSE
    SELECT * INTO v_rel FROM authz_int.shared_relations s
    WHERE s.object_type = p_type AND s.relation = p_relation AND s.subject = v_key;
    IF v_rel.relation IS NULL THEN
      RAISE EXCEPTION 'the policy does not allow sharing %.% with %', p_type, p_relation, v_key USING HINT = 'rowstile help AZ706';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_rel.shared_by)
       OR NOT authz.can(p_type, p_id, v_rel.shared_by) THEN
      RAISE EXCEPTION 'you cannot share % % (needs %)', p_type, p_id, v_rel.shared_by USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    SELECT string_agg(n, ', ') INTO v_need FROM unnest(v_rel.required) n WHERE NOT authz.can(p_type, p_id, n);
    IF v_need IS NOT NULL THEN
      RAISE EXCEPTION 'you cannot grant %.% on % %: you do not hold %', p_type, p_relation, p_type, p_id, v_need
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    IF NOT authz_int.share_if(p_type || '.' || p_relation || '.' || v_key, p_id, p_subject_type,
                              p_subject_id, p_subject_relation) THEN
      RAISE EXCEPTION 'the policy does not allow this share (%)', coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = v_rel.loc), '?') USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ706';
    END IF;
  END IF;
  IF p_caveat IS NOT NULL AND NOT EXISTS (SELECT 1 FROM authz_int.caveats WHERE name = p_caveat) THEN
    RAISE EXCEPTION 'no caveat % in the policy', p_caveat USING HINT = 'rowstile help AZ707';
  END IF;
  INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                            expires_at, created_by, starts_at, caveat, caveat_args)
  VALUES (p_type, p_id, p_relation, p_subject_type, p_subject_id, p_subject_relation,
          p_expires_at, authz_int.actor(), p_starts_at, p_caveat, p_caveat_args)
  ON CONFLICT ON CONSTRAINT shares_pkey
  DO UPDATE SET expires_at = EXCLUDED.expires_at, created_by = EXCLUDED.created_by,
                starts_at = EXCLUDED.starts_at, caveat = EXCLUDED.caveat, caveat_args = EXCLUDED.caveat_args;
END $f$;
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id bigint, p_relation text, p_subject_type text, p_subject_id bigint,
  p_subject_relation text DEFAULT '', p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void LANGUAGE sql AS
  $$ SELECT authz.share(p_type, p_id::text, p_relation, p_subject_type, p_subject_id::text, p_subject_relation,
                        p_expires_at, p_starts_at, p_caveat, p_caveat_args) $$;
CREATE OR REPLACE FUNCTION authz.share(p_type text, p_id bigint, p_relation text, p_subject_type text, p_subject_id text,
  p_subject_relation text DEFAULT '', p_expires_at timestamptz DEFAULT NULL, p_starts_at timestamptz DEFAULT NULL,
  p_caveat text DEFAULT NULL, p_caveat_args jsonb DEFAULT NULL) RETURNS void LANGUAGE sql AS
  $$ SELECT authz.share(p_type, p_id::text, p_relation, p_subject_type, p_subject_id, p_subject_relation,
                        p_expires_at, p_starts_at, p_caveat, p_caveat_args) $$;

-- Unshare: needs what sharing needs (the relation's 'shared by' permission)
CREATE OR REPLACE FUNCTION authz.unshare(p_type text, p_id text, p_relation text,
  p_subject_type text, p_subject_id text, p_subject_relation text DEFAULT '') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_by text;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  p_subject_id := authz_int.canon(p_subject_type, p_subject_id);
  v_by := coalesce(authz_int.manage_perm(p_type, p_relation,
                                         authz_int.subject_key(p_subject_type, p_subject_id, p_subject_relation)),
                   authz_int.manage_perm(p_type, p_relation));
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) OR v_by IS NULL
     OR NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = v_by)
     OR NOT authz.can(p_type, p_id, v_by) THEN
    RAISE EXCEPTION 'you cannot share % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  DELETE FROM authz.shares WHERE object_type = p_type AND object_id = p_id
    AND relation = p_relation AND subject_type = p_subject_type
    AND subject_id = p_subject_id AND subject_relation = p_subject_relation;
END $f$;
CREATE OR REPLACE FUNCTION authz.unshare(p_type text, p_id bigint, p_relation text, p_subject_type text, p_subject_id bigint,
  p_subject_relation text DEFAULT '') RETURNS void LANGUAGE sql AS
  $$ SELECT authz.unshare(p_type, p_id::text, p_relation, p_subject_type, p_subject_id::text, p_subject_relation) $$;
CREATE OR REPLACE FUNCTION authz.unshare(p_type text, p_id bigint, p_relation text, p_subject_type text, p_subject_id text,
  p_subject_relation text DEFAULT '') RETURNS void LANGUAGE sql AS
  $$ SELECT authz.unshare(p_type, p_id::text, p_relation, p_subject_type, p_subject_id, p_subject_relation) $$;

-- A link anyone holding the token can use: returns the token once (only its hash is stored).
-- Requests present it with SET LOCAL authz_ctx.links = '<token>'.
CREATE OR REPLACE FUNCTION authz.create_link(p_type text, p_id text, p_relation text, p_expires_at timestamptz DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_token text := replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
BEGIN
  PERFORM authz.share(p_type, p_id, p_relation, 'link', encode(sha256(convert_to(v_token, 'UTF8')), 'hex'),
                      '', p_expires_at);
  RETURN v_token;
END $f$;
CREATE OR REPLACE FUNCTION authz.create_link(p_type text, p_id bigint, p_relation text, p_expires_at timestamptz DEFAULT NULL)
RETURNS text LANGUAGE sql AS $$ SELECT authz.create_link(p_type, p_id::text, p_relation, p_expires_at) $$;

-- The relations whose links on an object the caller may see: every one it has links of if they may inspect it
-- (they can share it, or are an administrator), else those they may share with a link. NULL: none
CREATE FUNCTION authz_int.link_relations(p_type text, p_id text) RETURNS text[]
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF authz_int.may_inspect(p_type, p_id) THEN
    RETURN coalesce((SELECT array_agg(DISTINCT g.relation) FROM authz.shares g
                     WHERE g.object_type = p_type AND g.object_id = p_id AND g.subject_type = 'link'), '{}');
  END IF;
  RETURN (SELECT array_agg(s.relation) FROM authz_int.shared_relations s
          WHERE s.object_type = p_type AND s.subject = 'link'
            AND authz_int.may_manage(p_type, p_id, s.relation, 'link'));
END $f$;
-- The links on an object: SELECT * FROM authz.list_links('folder', 3). For those who can share it, or may make
-- such links. A link's id names it for authz.revoke_link: it is not the token, and opens nothing.
CREATE OR REPLACE FUNCTION authz.list_links(p_type text, p_id text)
RETURNS TABLE (id text, relation text, created_by text, created_at timestamptz, expires_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_relations text[];
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  v_relations := authz_int.link_relations(p_type, p_id);
  IF v_relations IS NULL THEN
    RAISE EXCEPTION 'you cannot see the links of % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  RETURN QUERY SELECT left(g.subject_id, 16), g.relation, g.created_by, g.created_at, g.expires_at
  FROM authz.shares g WHERE g.object_type = p_type AND g.object_id = p_id AND g.subject_type = 'link'
    AND g.relation = ANY (v_relations) ORDER BY g.created_at, g.subject_id;
END $f$;
-- Turn a link off, by its id in authz.list_links: needs what unsharing it needs
CREATE OR REPLACE FUNCTION authz.revoke_link(p_type text, p_id text, p_link text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_relations text[]; v record; v_found boolean := false;
BEGIN
  PERFORM authz_int.check_writable();
  p_id := authz_int.canon(p_type, p_id);
  v_relations := authz_int.link_relations(p_type, p_id);
  IF v_relations IS NULL THEN
    RAISE EXCEPTION 'you cannot turn off the links of % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  FOR v IN SELECT g.relation, g.subject_id FROM authz.shares g
           WHERE g.object_type = p_type AND g.object_id = p_id AND g.subject_type = 'link'
             AND g.relation = ANY (v_relations) AND left(g.subject_id, 16) = p_link LOOP
    IF NOT authz_int.may_manage(p_type, p_id, v.relation, 'link') THEN
      RAISE EXCEPTION 'you cannot turn off link % of % % (you could not unshare it)', p_link, p_type, p_id
        USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
    END IF;
    DELETE FROM authz.shares g WHERE g.object_type = p_type AND g.object_id = p_id AND g.relation = v.relation
      AND g.subject_type = 'link' AND g.subject_id = v.subject_id;
    v_found := true;
  END LOOP;
  IF NOT v_found THEN
    RAISE EXCEPTION 'no link % on % %', p_link, p_type, p_id USING HINT = 'rowstile help AZ708';
  END IF;
END $f$;
CREATE OR REPLACE FUNCTION authz.list_links(p_type text, p_id bigint) RETURNS TABLE (id text, relation text, created_by text, created_at timestamptz, expires_at timestamptz) LANGUAGE sql STABLE AS
  $$ SELECT * FROM authz.list_links(p_type, p_id::text) $$;
CREATE OR REPLACE FUNCTION authz.revoke_link(p_type text, p_id bigint, p_link text) RETURNS void LANGUAGE sql AS
  $$ SELECT authz.revoke_link(p_type, p_id::text, p_link) $$;

-- Custom roles: defined per owner (e.g. an org) by people with 'manage_roles' there
CREATE OR REPLACE FUNCTION authz.create_role(p_owner_type text, p_owner_id text, p_object_type text, p_name text,
  p_permissions text[]) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id bigint; v_bad text;
BEGIN
  PERFORM authz_int.check_writable();
  IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'manage_roles') THEN
    RAISE EXCEPTION '% has no manage_roles permission in the policy', p_owner_type USING HINT = 'rowstile help AZ707';
  END IF;
  IF authz.uid() IS NULL OR NOT authz.can(p_owner_type, p_owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage roles of % %', p_owner_type, p_owner_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF p_owner_type IS DISTINCT FROM coalesce(authz_int.role_owner_type(p_object_type), p_owner_type) THEN
    RAISE EXCEPTION 'custom roles on % belong to a % (the policy says where they come from), not to a %',
      p_object_type, authz_int.role_owner_type(p_object_type), p_owner_type USING HINT = 'rowstile help AZ706';
  END IF;
  SELECT string_agg(p, ', ') INTO v_bad FROM unnest(p_permissions) p
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.role_grantable g WHERE g.object_type = p_object_type AND g.permission = p);
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'custom roles on % cannot grant %', p_object_type, v_bad USING HINT = 'rowstile help AZ706';
  END IF;
  INSERT INTO authz.roles (owner_type, owner_id, object_type, name, created_by)
  VALUES (p_owner_type, authz_int.canon(p_owner_type, p_owner_id), p_object_type, p_name, authz.uid()::text)
  RETURNING id INTO v_id;
  INSERT INTO authz.role_permissions SELECT v_id, p FROM unnest(p_permissions) p ON CONFLICT DO NOTHING;
  RETURN v_id;
END $f$;
CREATE OR REPLACE FUNCTION authz.create_role(p_owner_type text, p_owner_id bigint, p_object_type text, p_name text,
  p_permissions text[]) RETURNS bigint LANGUAGE sql AS
  $$ SELECT authz.create_role(p_owner_type, p_owner_id::text, p_object_type, p_name, p_permissions) $$;
CREATE OR REPLACE FUNCTION authz.set_role_permissions(p_role bigint, p_permissions text[]) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.roles; v_bad text;
BEGIN
  PERFORM authz_int.check_writable();
  SELECT * INTO v FROM authz.roles WHERE id = p_role;
  IF v.id IS NULL OR authz.uid() IS NULL OR NOT authz.can(v.owner_type, v.owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage role %', p_role USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  SELECT string_agg(p, ', ') INTO v_bad FROM unnest(p_permissions) p
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.role_grantable g WHERE g.object_type = v.object_type AND g.permission = p);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'custom roles on % cannot grant %', v.object_type, v_bad USING HINT = 'rowstile help AZ706'; END IF;
  DELETE FROM authz.role_permissions WHERE role_id = p_role;
  INSERT INTO authz.role_permissions SELECT p_role, p FROM unnest(p_permissions) p ON CONFLICT DO NOTHING;
END $f$;
CREATE OR REPLACE FUNCTION authz.delete_role(p_role bigint) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.roles;
BEGIN
  PERFORM authz_int.check_writable();
  SELECT * INTO v FROM authz.roles WHERE id = p_role;
  IF v.id IS NULL OR authz.uid() IS NULL OR NOT authz.can(v.owner_type, v.owner_id, 'manage_roles') THEN
    RAISE EXCEPTION 'you cannot manage role %', p_role USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  DELETE FROM authz.roles WHERE id = p_role;
END $f$;
CREATE OR REPLACE FUNCTION authz.roles_of(p_owner_type text, p_owner_id text)
RETURNS TABLE (id bigint, object_type text, name text, permissions text[])
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF authz.uid() IS NULL OR NOT (
       (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'manage_roles')
        AND authz.can(p_owner_type, p_owner_id, 'manage_roles'))
    OR (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_owner_type AND perm = 'view')
        AND authz.can(p_owner_type, p_owner_id, 'view'))) THEN
    RAISE EXCEPTION 'you cannot see roles of % %', p_owner_type, p_owner_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  RETURN QUERY SELECT r.id, r.object_type, r.name,
    ARRAY(SELECT p.permission FROM authz.role_permissions p WHERE p.role_id = r.id ORDER BY 1)
    FROM authz.roles r WHERE r.owner_type = p_owner_type AND r.owner_id = p_owner_id ORDER BY r.id;
END $f$;
CREATE OR REPLACE FUNCTION authz.roles_of(p_owner_type text, p_owner_id bigint)
RETURNS TABLE (id bigint, object_type text, name text, permissions text[]) LANGUAGE sql STABLE AS
  $$ SELECT * FROM authz.roles_of(p_owner_type, p_owner_id::text) $$;

-- Why a write is or would be refused, as the signed-in user: an insert (p_row: the new row as JSON), or an
-- update or delete of the row whose id is p_id (for an update, p_row: the new values). NULL when that row isn't
-- there or the user can't see it (404, not 403). SELECT authz.explain_rule('app.files', 'update', '11')
CREATE OR REPLACE FUNCTION authz.explain_rule(p_table text, p_command text, p_id text DEFAULT NULL, p_row jsonb DEFAULT NULL)
RETURNS text[] LANGUAGE plpgsql STABLE SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF p_command IS NULL OR p_command NOT IN ('insert', 'update', 'delete') THEN
    RAISE EXCEPTION 'explain_rule explains insert, update or delete, not %', p_command USING ERRCODE = 'invalid_parameter_value', HINT = 'rowstile help AZ710';
  END IF;
  CASE p_table
    WHEN 'app.documents' THEN RETURN authz_gen."app.documents:rules:explain"(p_command, p_id, p_row);
    ELSE RAISE EXCEPTION 'the policy has no rules for table %', p_table USING ERRCODE = 'undefined_table', HINT = 'rowstile help AZ707';
  END CASE;
END $f$;

-- Which of these people (or principals of another type) hold a permission: who to tell about a change.
-- It signs each one in with authz.act_as(), as the caller: so only a backend trusted to sign anyone in can
-- use it, as it could ask authz.can for each one itself. Not in a session limited by scopes or view-as. SELECT * FROM authz.who_among('chat', '7', 'read', ARRAY['1', '2'])
CREATE OR REPLACE FUNCTION authz.who_among(p_type text, p_id text, p_perm text, p_users text[], p_principal_type text DEFAULT 'user')
RETURNS SETOF text LANGUAGE plpgsql VOLATILE SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := nullif(current_setting('authz.user_id', true), '');
        v_pt text := coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user');
        v_u text;
BEGIN
  IF coalesce(current_setting('authz.scopes', true), '') <> '' OR coalesce(current_setting('authz.acting_user', true), '') <> '' THEN
    RAISE EXCEPTION 'authz.who_among() signs people in, which a session limited by scopes or view-as may not'
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  BEGIN
    FOREACH v_u IN ARRAY coalesce(p_users, '{}') LOOP
      PERFORM authz.act_as(p_principal_type, v_u);
      IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_u; END IF;
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    PERFORM authz.act_as(v_pt, v_me);
    RAISE;
  END;
  PERFORM authz.act_as(v_pt, v_me);
END $f$;
CREATE OR REPLACE FUNCTION authz.who_among(p_type text, p_id bigint, p_perm text, p_users text[], p_principal_type text DEFAULT 'user') RETURNS SETOF text LANGUAGE sql VOLATILE AS
  $$ SELECT * FROM authz.who_among(p_type, p_id::text, p_perm, p_users, p_principal_type) $$;

-- these functions call each other; their bodies are checked when first used
SET LOCAL check_function_bodies = off;

CREATE FUNCTION authz_int."team__member__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT s."user_id" FROM "app"."team_members" s WHERE s."team_id" = p_id
$f$;

CREATE FUNCTION authz_int."document__owner__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT r."owner_id" FROM "app"."documents" r WHERE r."id" = p_id AND r."owner_id" IS NOT NULL
$f$;

CREATE FUNCTION authz_int."document__editor__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT g.subject_id::bigint FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = (p_id)::text AND g.relation = 'editor' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id <> '*')
  UNION ALL
  (SELECT x FROM authz.shares g, LATERAL authz_int."team__member__who"(g.subject_id::bigint) x WHERE g.object_type = 'document' AND g.object_id = (p_id)::text AND g.relation = 'editor' AND g.subject_type = 'team' AND g.subject_relation = 'member')
$f$;

CREATE FUNCTION authz_int."document__viewer__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT g.subject_id::bigint FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = (p_id)::text AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id <> '*')
  UNION ALL
  (SELECT x FROM authz.shares g, LATERAL authz_int."team__member__who"(g.subject_id::bigint) x WHERE g.object_type = 'document' AND g.object_id = (p_id)::text AND g.relation = 'viewer' AND g.subject_type = 'team' AND g.subject_relation = 'member')
$f$;

CREATE FUNCTION authz_int."document__share__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  SELECT x FROM authz_int."document__owner__who"(p_id) x
$f$;

CREATE FUNCTION authz_int."document__edit__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT x FROM authz_int."document__share__who"(p_id) x)
  UNION ALL
  (SELECT x FROM authz_int."document__editor__who"(p_id) x)
$f$;

CREATE FUNCTION authz_int."document__view__who"(p_id bigint) RETURNS SETOF bigint
LANGUAGE sql STABLE STRICT SECURITY DEFINER SET search_path FROM CURRENT ROWS 50 AS $f$
  (SELECT x FROM authz_int."document__edit__who"(p_id) x)
  UNION ALL
  (SELECT x FROM authz_int."document__viewer__who"(p_id) x)
$f$;

CREATE FUNCTION authz_int."team__member__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT s."team_id" AS id FROM "app"."team_members" s WHERE s."user_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || 'member: a row in app.team_members names you' || '';
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold team.member';
END $f$;

CREATE FUNCTION authz_int."document__owner__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT r."id" AS id FROM "app"."documents" r WHERE r."owner_id" = (SELECT authz.uid())) THEN
    RETURN NEXT pad || 'yes  ' || 'owner: owner_id is you' || '';
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold document.owner';
END $f$;

CREATE FUNCTION authz_int."document__editor__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'editor' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    RETURN NEXT pad || 'yes  ' || 'editor: shared with you' || coalesce((SELECT concat(' (by ', coalesce(g.created_by, 'an admin'), coalesce(', until ' || g.expires_at, ''), coalesce(', from ' || g.starts_at, ''), coalesce(', caveat ' || g.caveat, ''), ')') FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = p_id::text AND g.relation = 'editor' AND g.subject_type = 'user' AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL ORDER BY g.created_at LIMIT 1), '');
    RETURN;
  END IF;
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'editor' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    FOR v_t IN SELECT x.gid::text AS gid FROM (SELECT g.subject_id AS gid FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = p_id::text AND g.relation = 'editor' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) x LIMIT 1 LOOP
      RETURN NEXT pad || 'yes  ' || 'editor: shared with' || ' team ' || v_t.gid || ', and you are member there';
      RETURN QUERY SELECT * FROM authz_int."team__member__why"(v_t.gid::bigint, p_depth + 1, p_seen);
    END LOOP;
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold document.editor';
END $f$;

CREATE FUNCTION authz_int."document__viewer__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_t record;
BEGIN
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'viewer' AND g.subject_type = 'user' AND g.subject_relation = '' AND g.subject_id = (SELECT authz.uid()::text) AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    RETURN NEXT pad || 'yes  ' || 'viewer: shared with you' || coalesce((SELECT concat(' (by ', coalesce(g.created_by, 'an admin'), coalesce(', until ' || g.expires_at, ''), coalesce(', from ' || g.starts_at, ''), coalesce(', caveat ' || g.caveat, ''), ')') FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = p_id::text AND g.relation = 'viewer' AND g.subject_type = 'user' AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL ORDER BY g.created_at LIMIT 1), '');
    RETURN;
  END IF;
  IF p_id IN (SELECT g.object_id::bigint AS id FROM authz.shares g WHERE g.object_type = 'document' AND g.relation = 'viewer' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) THEN
    FOR v_t IN SELECT x.gid::text AS gid FROM (SELECT g.subject_id AS gid FROM authz.shares g WHERE g.object_type = 'document' AND g.object_id = p_id::text AND g.relation = 'viewer' AND g.subject_type = 'team' AND g.subject_relation = 'member' AND g.subject_id IN (SELECT id::text FROM authz_int."team__member") AND (g.expires_at IS NULL OR g.expires_at > now()) AND (g.starts_at IS NULL OR g.starts_at <= now()) AND g.caveat IS NULL) x LIMIT 1 LOOP
      RETURN NEXT pad || 'yes  ' || 'viewer: shared with' || ' team ' || v_t.gid || ', and you are member there';
      RETURN QUERY SELECT * FROM authz_int."team__member__why"(v_t.gid::bigint, p_depth + 1, p_seen);
    END LOOP;
    RETURN;
  END IF;
  RETURN NEXT pad || 'no   you do not hold document.viewer';
END $f$;

CREATE FUNCTION authz_int."document__share__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."document__share");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'document.share = owner';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."document__owner");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'owner';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."document__owner__why"(p_id, p_depth + 1, p_seen); END IF;
  END;
END $f$;

CREATE FUNCTION authz_int."document__edit__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."document__edit");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'document.edit = share or editor';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."document__share");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'share';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."document__share__why"(p_id, p_depth + 1, p_seen); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."document__editor");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'editor';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."document__editor__why"(p_id, p_depth + 1, p_seen); END IF;
  END;
END $f$;

CREATE FUNCTION authz_int."document__view__why"(p_id bigint, p_depth int, p_seen text[])
RETURNS SETOF text LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
DECLARE pad text := repeat('  ', p_depth); v_ok boolean; v_done boolean := false; v_t record;
        v_holds boolean := p_id IN (SELECT id FROM authz_int."document__view");
BEGIN
  IF p_depth > 60 THEN RETURN NEXT pad || '...'; RETURN; END IF;
  RETURN NEXT pad || 'document.view = edit or viewer';
  BEGIN
    v_ok := (p_id) IN (SELECT id FROM authz_int."document__edit");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'edit';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."document__edit__why"(p_id, p_depth + 1, p_seen); END IF;
    v_ok := (p_id) IN (SELECT id FROM authz_int."document__viewer");
    RETURN NEXT pad || CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || 'viewer';
    IF v_ok AND NOT v_done THEN v_done := true; RETURN QUERY SELECT * FROM authz_int."document__viewer__why"(p_id, p_depth + 1, p_seen); END IF;
  END;
END $f$;

-- May the signed-in user see this object (select it)? A hidden object reads as a missing one
CREATE FUNCTION authz_int.visible(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path FROM CURRENT AS $f$
BEGIN
  IF NOT coalesce(pg_catalog.pg_input_is_valid(p_id, (SELECT keytype FROM authz_int.types WHERE name = p_type)), false) THEN
    RETURN false;
  END IF;
  CASE p_type
    WHEN 'user' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."users" "users" WHERE "users"."id" = p_id::bigint
        AND true);
    WHEN 'team' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."teams" "teams" WHERE "teams"."id" = p_id::bigint
        AND true);
    WHEN 'document' THEN
      RETURN EXISTS (SELECT 1 FROM "app"."documents" "documents" WHERE "documents"."id" = p_id::bigint
        AND (SELECT authz_int.scope_cmd('app.documents', 'select')) AND (coalesce("documents"."owner_id" = (SELECT authz.uid()), false)
    OR EXISTS (SELECT 1 FROM authz_gen."document__editor" v WHERE v.id = "documents"."id")
    OR EXISTS (SELECT 1 FROM authz_gen."document__viewer" v WHERE v.id = "documents"."id")));
    ELSE RETURN false;
  END CASE;
END $f$;

-- May the current user look at who has access to this object? (they can share it, or the caller is an
-- administrator: the policy's owner, a superuser or BYPASSRLS)
CREATE FUNCTION authz_int.may_inspect(p_type text, p_id text) RETURNS boolean
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF authz_int.caller_is_admin() THEN RETURN true; END IF;
  RETURN EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'share')
     AND authz.can(p_type, p_id, 'share');
END $f$;

-- Everyone who holds a permission on an object: SELECT * FROM authz.who('folder', 3, 'view')
-- Candidates come from the data (a superset); each is checked with authz.can, as that user.
CREATE OR REPLACE FUNCTION authz.who(p_type text, p_id text, p_perm text) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_c text;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_bigint bigint;
BEGIN
  IF NOT authz_int.may_inspect(p_type, p_id) OR NOT authz_int.scope_perm(p_type, p_perm) THEN
    RAISE EXCEPTION 'you cannot see who has access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  BEGIN
    PERFORM set_config('authz.scopes', '', true);   -- each candidate is checked with full rights
    PERFORM set_config('authz.principal_type', '', true);   -- candidates are users
    CASE p_type
    WHEN 'document' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."document__share__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'edit' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."document__edit__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        WHEN 'view' THEN
          FOR v_c IN SELECT DISTINCT x::text FROM authz_int."document__view__who"(v_bigint) x WHERE EXISTS (SELECT 1 FROM "app"."users" u WHERE u."id" = x) LOOP
            PERFORM set_config('authz.user_id', v_c, true);
            PERFORM authz_int.sign();
            IF authz.can(p_type, p_id, p_perm) THEN RETURN NEXT v_c; END IF;
          END LOOP;
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('authz.user_id', v_me, true);
    PERFORM set_config('authz.principal_type', v_pt, true);
    PERFORM set_config('authz.scopes', v_scopes, true);
    PERFORM authz_int.sign();
    RAISE;
  END;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

-- Why the current user (or, for people who may inspect the object, another user) holds a
-- permission, or what is missing: SELECT * FROM authz.explain('file', 11, 'edit')
CREATE OR REPLACE FUNCTION authz.explain(p_type text, p_id text, p_perm text, p_user text DEFAULT NULL) RETURNS SETOF text
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_ok boolean; v_bigint bigint;
        v_pt text := coalesce(current_setting('authz.principal_type', true), '');
BEGIN
  -- another user's access: only for people who may inspect the object (the signed-in user may explain their own;
  -- a service whose id is a user's may not)
  IF p_user IS NOT NULL AND authz_int.canon('user', p_user) IS DISTINCT FROM authz.uid()::text
     AND NOT authz_int.may_inspect(p_type, p_id) THEN
    RAISE EXCEPTION 'you cannot inspect access to % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  -- people who can't see the object learn nothing about it, whatever else they hold on it (as for a missing one)
  IF p_user IS NULL AND NOT authz_int.may_inspect(p_type, p_id) AND NOT authz_int.visible(p_type, p_id) THEN
    RETURN NEXT 'no   you have no access to ' || p_type || ' ' || p_id;
    RETURN;
  END IF;
  BEGIN
    IF p_user IS NOT NULL THEN
      PERFORM set_config('authz.user_id', p_user, true);
      PERFORM set_config('authz.principal_type', '', true);
      PERFORM authz_int.sign();
    END IF;
    v_ok := authz.can(p_type, p_id, p_perm);
    RETURN NEXT CASE WHEN v_ok THEN 'yes  ' ELSE 'no   ' END || coalesce(coalesce(nullif(current_setting('authz.principal_type', true), ''), 'user') || ' ' || nullif(current_setting('authz.user_id', true), ''), 'nobody')
      || ' ' || CASE WHEN v_ok THEN 'holds ' ELSE 'does not hold ' END || p_perm || ' on ' || p_type || ' ' || p_id;
    CASE p_type
    WHEN 'document' THEN
      IF NOT pg_catalog.pg_input_is_valid(p_id, 'bigint') THEN RETURN; END IF;
      v_bigint := p_id::bigint;
      CASE p_perm
        WHEN 'share' THEN RETURN QUERY SELECT * FROM authz_int."document__share__why"(v_bigint, 1, '{}');
        WHEN 'edit' THEN RETURN QUERY SELECT * FROM authz_int."document__edit__why"(v_bigint, 1, '{}');
        WHEN 'view' THEN RETURN QUERY SELECT * FROM authz_int."document__view__why"(v_bigint, 1, '{}');
        ELSE RAISE EXCEPTION 'no permission %.% in the policy', p_type, p_perm USING HINT = 'rowstile help AZ707';
      END CASE;
    ELSE
      RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707';
  END CASE;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('authz.user_id', v_me, true);
    PERFORM set_config('authz.principal_type', v_pt, true);
    PERFORM authz_int.sign();
    RAISE;
  END;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM authz_int.sign();
END $f$;

-- The shares on an object (for a sharing dialog): SELECT * FROM authz.list_shares('folder', 3)
CREATE OR REPLACE FUNCTION authz.list_shares(p_type text, p_id text)
RETURNS TABLE (relation text, role text, subject_type text, subject_id text, subject_relation text,
               expires_at timestamptz, starts_at timestamptz, caveat text, created_by text, created_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  IF NOT authz_int.may_inspect(p_type, p_id) THEN
    RAISE EXCEPTION 'you cannot see the shares of % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  RETURN QUERY SELECT g.relation, (SELECT r.name FROM authz.roles r WHERE 'role:' || r.id = g.relation),
    g.subject_type, CASE WHEN g.subject_type = 'link' THEN '(link)' ELSE g.subject_id END, g.subject_relation,
    g.expires_at, g.starts_at, g.caveat, g.created_by, g.created_at
  FROM authz.shares g WHERE g.object_type = p_type AND g.object_id = p_id ORDER BY g.created_at, g.relation;
END $f$;
CREATE OR REPLACE FUNCTION authz.who(p_type text, p_id bigint, p_perm text) RETURNS SETOF text LANGUAGE sql STABLE AS
  $$ SELECT * FROM authz.who(p_type, p_id::text, p_perm) $$;
CREATE OR REPLACE FUNCTION authz.explain(p_type text, p_id bigint, p_perm text, p_user text DEFAULT NULL) RETURNS SETOF text LANGUAGE sql STABLE AS
  $$ SELECT * FROM authz.explain(p_type, p_id::text, p_perm, p_user) $$;
CREATE OR REPLACE FUNCTION authz.list_shares(p_type text, p_id bigint) RETURNS TABLE (relation text, role text, subject_type text, subject_id text, subject_relation text, expires_at timestamptz, starts_at timestamptz, caveat text, created_by text, created_at timestamptz) LANGUAGE sql STABLE AS
  $$ SELECT * FROM authz.list_shares(p_type, p_id::text) $$;

-- Invariants: checked as everyone who can sign in (each user, each other principal as 'service:3') and as
-- nobody; returns the violations
CREATE OR REPLACE FUNCTION authz.check_invariants() RETURNS TABLE (invariant text, user_id text, object_ids text[])
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := coalesce(current_setting('authz.user_id', true), ''); v_pt text := coalesce(current_setting('authz.principal_type', true), '');
        v_scopes text := coalesce(current_setting('authz.scopes', true), ''); v_p text; v_u text; v_ids text[];
BEGIN
  BEGIN
    PERFORM set_config('authz.scopes', '', true);
    FOR v_p, v_u IN SELECT '', '' UNION ALL SELECT '', x."id"::text FROM "app"."users" x LOOP
      PERFORM set_config('authz.principal_type', v_p, true);
      PERFORM set_config('authz.user_id', v_u, true);
      PERFORM authz_int.sign();
      NULL;
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('authz.user_id', v_me, true);
    PERFORM set_config('authz.principal_type', v_pt, true);
    PERFORM set_config('authz.scopes', v_scopes, true);
    PERFORM authz_int.sign();
    RAISE;
  END;
  PERFORM set_config('authz.user_id', v_me, true);
  PERFORM set_config('authz.principal_type', v_pt, true);
  PERFORM set_config('authz.scopes', v_scopes, true);
  PERFORM authz_int.sign();
END $f$;

SET LOCAL check_function_bodies = on;

-- API keys: a signed-in user's own, or a principal's (a service's) made by someone holding
-- manage_keys on it; only a hash is kept
CREATE OR REPLACE FUNCTION authz.create_api_key(p_name text, p_scopes text DEFAULT '', p_expires_at timestamptz DEFAULT NULL,
  p_principal_type text DEFAULT NULL, p_principal_id text DEFAULT NULL)
RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_token text := 'ak_' || replace(gen_random_uuid()::text || gen_random_uuid()::text, '-', '');
        v_scopes text[] := ARRAY(SELECT DISTINCT btrim(x) FROM unnest(string_to_array(coalesce(p_scopes, ''), ',')) x
                                 WHERE btrim(x) <> '' ORDER BY 1);
        v_cur text[] := authz_int.scopes_active(); v_bad text;
        v_type text := coalesce(p_principal_type, 'user'); v_id text;
BEGIN
  PERFORM authz_int.check_writable();
  IF p_principal_id IS NULL THEN
    IF v_type <> 'user' OR authz.uid() IS NULL THEN
      RAISE EXCEPTION 'sign in to create an API key' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ701';
    END IF;
    v_id := authz.uid()::text;
  ELSE
    v_id := authz_int.canon(v_type, p_principal_id);
    PERFORM authz_int.check_manage_keys(v_type, v_id);
  END IF;
  SELECT string_agg(x, ', ') INTO v_bad FROM unnest(v_scopes) x
  WHERE NOT EXISTS (SELECT 1 FROM authz_int.scope_items WHERE scope = x);
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'no scope % in the policy', v_bad USING HINT = 'rowstile help AZ707'; END IF;
  IF v_cur IS NOT NULL AND (cardinality(v_scopes) = 0 OR NOT v_scopes <@ v_cur) THEN
    RAISE EXCEPTION 'a key cannot have more scopes than the session creating it' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  INSERT INTO authz.api_keys (user_id, principal_type, name, prefix, hash, scopes, expires_at)
  VALUES (v_id, v_type, p_name, left(v_token, 10), encode(sha256(convert_to(v_token, 'UTF8')), 'hex'),
          array_to_string(v_scopes, ','), p_expires_at);
  PERFORM authz_int.audit('create_api_key', v_type, v_id, NULL, NULL, NULL, NULL,
                          jsonb_build_object('name', p_name, 'scopes', v_scopes, 'expires_at', p_expires_at));
  RETURN v_token;
END $f$;

-- May the signed-in principal manage the keys of this one? Needs `can manage_keys` on its type.
CREATE FUNCTION authz_int.check_manage_keys(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = p_type AND principal) THEN
    RAISE EXCEPTION 'no type % that signs in (type ... principal) in the policy', p_type USING HINT = 'rowstile help AZ707';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'manage_keys') THEN
    RAISE EXCEPTION 'the policy gives % no manage_keys permission, so nobody manages its keys', p_type
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ707';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) OR NOT coalesce(authz.can(p_type, p_id, 'manage_keys'), false) THEN
    RAISE EXCEPTION 'you cannot manage the keys of % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
END $f$;

-- Your keys, or (with manage_keys on it) a principal's
CREATE OR REPLACE FUNCTION authz.list_api_keys(p_principal_type text DEFAULT NULL, p_principal_id text DEFAULT NULL)
RETURNS TABLE (id bigint, name text, prefix text, scopes text, created_at timestamptz, expires_at timestamptz,
               last_used_at timestamptz, revoked_at timestamptz)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_type text; v_id text;
BEGIN
  IF p_principal_id IS NULL THEN
    SELECT p.principal_type, p.principal_id INTO v_type, v_id FROM authz.principal() p;
  ELSE
    v_type := coalesce(p_principal_type, 'user');
    v_id := authz_int.canon(v_type, p_principal_id);
    PERFORM authz_int.check_manage_keys(v_type, v_id);
  END IF;
  RETURN QUERY SELECT k.id, k.name, k.prefix, k.scopes, k.created_at, k.expires_at, k.last_used_at, k.revoked_at
  FROM authz.api_keys k WHERE k.user_id = v_id AND k.principal_type = v_type ORDER BY k.id;
END $f$;

-- Revoke a key: your own, a user's you may inspect, or a principal's you manage the keys of
CREATE OR REPLACE FUNCTION authz.revoke_api_key(p_id bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz.api_keys;
BEGIN
  PERFORM authz_int.check_writable();
  SELECT * INTO k FROM authz.api_keys WHERE id = p_id AND revoked_at IS NULL;
  IF k.id IS NULL OR NOT (
       EXISTS (SELECT 1 FROM authz.principal() p WHERE p.principal_type = k.principal_type AND p.principal_id = k.user_id)
       OR (k.principal_type = 'user' AND authz_int.may_inspect('user', k.user_id))
       OR (EXISTS (SELECT 1 FROM authz_int.perms WHERE type = k.principal_type AND perm = 'manage_keys')
           AND EXISTS (SELECT 1 FROM authz.principal())
           AND coalesce(authz.can(k.principal_type, k.user_id, 'manage_keys'), false))) THEN
    RAISE EXCEPTION 'no API key % of yours', p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ708';
  END IF;
  UPDATE authz.api_keys SET revoked_at = now() WHERE id = p_id;
  PERFORM authz_int.audit('revoke_api_key', k.principal_type, k.user_id, NULL, NULL, NULL, NULL,
                          jsonb_build_object('key', p_id));
END $f$;

-- Say who is asking, for this transaction: SELECT authz.act_as('user', '42') (NULL, NULL: nobody), first in each
-- transaction. For the app's backend, which signs people in itself; the session is signed, so nothing but this
-- and the logins can change who is signed in. The app role (and its members) may call it.
CREATE OR REPLACE FUNCTION authz.act_as(p_type text, p_id text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  IF p_id IS NOT NULL AND coalesce(p_type, 'user') <> 'user'
     AND NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = p_type AND principal) THEN
    RAISE EXCEPTION '% is not a type that signs in', p_type USING ERRCODE = 'invalid_parameter_value',
      HINT = 'principal types are marked "principal" in the policy: type service = app.services principal (rowstile help AZ707)';
  END IF;
  -- stored as every other id is ('05' is 5), so the audit and created_by name the user as shares do
  PERFORM set_config('authz.user_id', coalesce(authz_int.canon(coalesce(p_type, 'user'), p_id), ''), true);
  PERFORM set_config('authz.principal_type', CASE WHEN p_id IS NULL OR coalesce(p_type, 'user') = 'user' THEN '' ELSE p_type END, true);
  PERFORM set_config('authz.scopes', '', true);
  PERFORM set_config('authz.acting_user', '', true);
  PERFORM authz_int.sign();
END $f$;

-- Sign in with an API key for this transaction: SELECT authz.login_key('ak_...'). Returns who:
-- a user's id, or type:id for another principal
CREATE OR REPLACE FUNCTION authz.login_key(p_token text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE k authz.api_keys;
BEGIN
  SELECT * INTO k FROM authz.api_keys WHERE hash = encode(sha256(convert_to(coalesce(p_token, ''), 'UTF8')), 'hex');
  IF k.id IS NULL OR k.revoked_at IS NOT NULL OR (k.expires_at IS NOT NULL AND k.expires_at <= now()) THEN
    RAISE EXCEPTION 'invalid API key' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  PERFORM set_config('authz.user_id', k.user_id, true);
  PERFORM set_config('authz.principal_type', CASE WHEN k.principal_type = 'user' THEN '' ELSE k.principal_type END, true);
  PERFORM set_config('authz.scopes', k.scopes, true);
  PERFORM set_config('authz.acting_user', '', true);
  PERFORM authz_int.sign();
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    PERFORM set_config('authz.user_id', '', true);
    PERFORM set_config('authz.principal_type', '', true);
    RAISE EXCEPTION 'invalid API key' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  -- when it was last used, to the minute: never waiting on another request with the key (the row they
  -- lock), and not at all in a read-only transaction (a replica, a GET)
  IF pg_catalog.current_setting('transaction_read_only') = 'off' THEN
    UPDATE authz.api_keys SET last_used_at = now()
    WHERE id = (SELECT x.id FROM authz.api_keys x
                WHERE x.id = k.id AND (x.last_used_at IS NULL OR x.last_used_at < now() - interval '1 minute')
                FOR UPDATE SKIP LOCKED);
  END IF;
  RETURN authz_int.actor();
END $f$;

-- HMAC-SHA256 in SQL, for JWT signatures (HS256)
CREATE FUNCTION authz_int.hmac_sha256(p_key bytea, p_msg bytea) RETURNS bytea
LANGUAGE plpgsql IMMUTABLE STRICT AS $f$
DECLARE k bytea := p_key; ipad bytea; opad bytea;
BEGIN
  IF length(k) > 64 THEN k := sha256(k); END IF;
  k := k || decode(repeat('00', 64 - length(k)), 'hex');
  ipad := k; opad := k;
  FOR i IN 0..63 LOOP
    ipad := set_byte(ipad, i, get_byte(k, i) # 54);
    opad := set_byte(opad, i, get_byte(k, i) # 92);
  END LOOP;
  RETURN sha256(opad || sha256(ipad || p_msg));
END $f$;
CREATE FUNCTION authz_int.b64url(p text) RETURNS bytea
LANGUAGE sql IMMUTABLE STRICT AS $f$
  SELECT decode(rpad(translate(p, '-_', '+/'), ((length(p) + 3) / 4) * 4, '='), 'base64') $f$;

-- Sign in with a JWT (HS256) for this transaction: SELECT authz.login_jwt('eyJ...')
-- Settings (authz.settings): jwt_secret (required), jwt_issuer, jwt_audience, jwt_user_claim (default sub),
-- jwt_type_claim (a claim naming the principal's type, for services; absent or 'user': a user).
-- Tokens must carry exp.
-- A 'scope' claim (space separated) limits the transaction to those policy scopes.
CREATE OR REPLACE FUNCTION authz.login_jwt(p_token text) RETURNS text
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE parts text[] := string_to_array(coalesce(p_token, ''), '.'); v_head jsonb; v_claims jsonb; v_secret text;
        v_user text; v_type text; v_scopes text[]; v_now numeric := extract(epoch FROM now()); v_want text;
BEGIN
  SELECT value INTO v_secret FROM authz.settings WHERE key = 'jwt_secret';
  IF v_secret IS NULL THEN RAISE EXCEPTION 'JWT login is not configured (authz.settings jwt_secret)' USING HINT = 'rowstile help AZ703'; END IF;
  BEGIN
    IF cardinality(parts) <> 3 THEN RAISE EXCEPTION 'bad'; END IF;
    v_head := convert_from(authz_int.b64url(parts[1]), 'UTF8')::jsonb;
    v_claims := convert_from(authz_int.b64url(parts[2]), 'UTF8')::jsonb;
    IF v_head->>'alg' IS DISTINCT FROM 'HS256'
       OR authz_int.b64url(parts[3]) <> authz_int.hmac_sha256(convert_to(v_secret, 'UTF8'),
                                                              convert_to(parts[1] || '.' || parts[2], 'UTF8')) THEN
      RAISE EXCEPTION 'bad';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'invalid token' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END;
  -- an expiry is required; both are numbers of seconds
  IF jsonb_typeof(v_claims->'exp') IS DISTINCT FROM 'number' OR (v_claims->>'exp')::numeric <= v_now
     OR (v_claims ? 'nbf' AND (jsonb_typeof(v_claims->'nbf') <> 'number' OR (v_claims->>'nbf')::numeric > v_now)) THEN
    RAISE EXCEPTION 'token expired or not yet valid' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  SELECT value INTO v_want FROM authz.settings WHERE key = 'jwt_issuer';
  IF v_want IS NOT NULL AND v_claims->>'iss' IS DISTINCT FROM v_want THEN
    RAISE EXCEPTION 'token from another issuer' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  SELECT value INTO v_want FROM authz.settings WHERE key = 'jwt_audience';
  -- (coalesce: without the claim both sides are NULL, and a token that names no audience is not for this one)
  IF v_want IS NOT NULL AND NOT coalesce(v_claims->>'aud' = v_want
       OR (jsonb_typeof(v_claims->'aud') = 'array' AND v_claims->'aud' ? v_want), false) THEN
    RAISE EXCEPTION 'token for another audience' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  v_user := v_claims->>coalesce((SELECT value FROM authz.settings WHERE key = 'jwt_user_claim'), 'sub');
  v_type := v_claims->>(SELECT value FROM authz.settings WHERE key = 'jwt_type_claim');
  IF coalesce(v_type, 'user') <> 'user' AND NOT EXISTS (SELECT 1 FROM authz_int.types WHERE name = v_type AND principal) THEN
    RAISE EXCEPTION 'the token names a type that does not sign in' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  PERFORM set_config('authz.user_id', coalesce(authz_int.canon(coalesce(v_type, 'user'), v_user), ''), true);
  PERFORM set_config('authz.principal_type', CASE WHEN coalesce(v_type, 'user') = 'user' THEN '' ELSE v_type END, true);
  PERFORM set_config('authz.acting_user', '', true);
  IF v_claims ? 'scope' THEN
    v_scopes := ARRAY(SELECT x FROM unnest(string_to_array(v_claims->>'scope', ' ')) x
                      WHERE EXISTS (SELECT 1 FROM authz_int.scope_items WHERE scope = x));
    PERFORM set_config('authz.scopes', CASE WHEN cardinality(v_scopes) = 0 THEN '(none)'
                                            ELSE array_to_string(v_scopes, ',') END, true);
  ELSE
    PERFORM set_config('authz.scopes', '', true);
  END IF;
  PERFORM authz_int.sign();
  IF NOT EXISTS (SELECT 1 FROM authz.principal()) THEN
    PERFORM set_config('authz.user_id', '', true);
    PERFORM set_config('authz.principal_type', '', true);
    RAISE EXCEPTION 'the token names no active user' USING ERRCODE = 'invalid_authorization_specification', HINT = 'rowstile help AZ703';
  END IF;
  RETURN authz_int.actor();
END $f$;

-- Support staff see what a user sees, read-only, for this transaction, with a reason on record:
-- SELECT authz.view_as('42', 'ticket 1234')  (the user type has no impersonate permission: administrators only)
CREATE OR REPLACE FUNCTION authz.view_as(p_user text, p_reason text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me text := nullif(current_setting('authz.user_id', true), '');
        v_pt text := coalesce(current_setting('authz.principal_type', true), ''); v_actor text := authz_int.actor();
BEGIN
  IF coalesce(current_setting('authz.acting_user', true), '') <> '' THEN
    RAISE EXCEPTION 'already viewing as someone' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ704';
  END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN
    RAISE EXCEPTION 'say why (the reason is kept in the audit trail)' USING HINT = 'rowstile help AZ710';
  END IF;
  IF NOT (authz_int.caller_is_admin()
          ) THEN
    RAISE EXCEPTION 'you cannot view as user %', p_user USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  PERFORM set_config('authz.user_id', coalesce(authz_int.canon('user', p_user), ''), true);
  PERFORM set_config('authz.principal_type', '', true);
  PERFORM authz_int.sign();
  IF authz.uid() IS NULL THEN
    PERFORM set_config('authz.user_id', coalesce(v_me, ''), true);
    PERFORM set_config('authz.principal_type', v_pt, true);
    PERFORM authz_int.sign();
    RAISE EXCEPTION 'there is no active user %', p_user USING HINT = 'rowstile help AZ708';
  END IF;
  PERFORM set_config('authz.acting_user', coalesce(v_actor, authz_int.caller_role()), true);
  PERFORM set_config('authz.scopes', 'read', true);
  PERFORM authz_int.sign();
  PERFORM set_config('authz_ctx.reason', p_reason, true);
  PERFORM authz_int.audit('view_as', 'user', authz_int.canon('user', p_user), NULL, NULL, NULL, NULL, NULL);
END $f$;

-- Replace a group's members with the list your identity provider sends (administrators, sync jobs):
-- SELECT * FROM authz.sync_members('team', '10', 'member', ARRAY['1', '2'])
CREATE OR REPLACE FUNCTION authz.sync_members(p_type text, p_id text, p_relation text, p_members text[],
  OUT added int, OUT removed int)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  CASE p_type || '.' || p_relation
    WHEN 'team.member' THEN
      WITH want AS (SELECT DISTINCT x::bigint AS m FROM unnest(p_members) x),
      del AS (DELETE FROM "app"."team_members" s WHERE s."team_id" = p_id::bigint AND s."user_id" NOT IN (SELECT m FROM want) RETURNING 1),
      ins AS (INSERT INTO "app"."team_members" ("team_id", "user_id") SELECT p_id::bigint, w.m FROM want w
              WHERE NOT EXISTS (SELECT 1 FROM "app"."team_members" s WHERE s."team_id" = p_id::bigint AND s."user_id" = w.m) RETURNING 1)
      SELECT (SELECT count(*) FROM ins)::int, (SELECT count(*) FROM del)::int INTO added, removed;
    ELSE RAISE EXCEPTION '%.% has no single table of members to sync (it needs one source: table(group -> user), without where)',
      p_type, p_relation USING HINT = 'rowstile help AZ707';
  END CASE;
  PERFORM authz_int.audit('sync_members', p_type, p_id, p_relation, 'user', NULL, NULL,
                          jsonb_build_object('added', added, 'removed', removed, 'members', p_members));
END $f$;

-- Who may manage a relation on an object: the permission that shares it (with users, when asked)
CREATE FUNCTION authz_int.manage_perm(p_type text, p_relation text, p_subject text DEFAULT NULL) RETURNS text
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT CASE
    WHEN p_relation LIKE 'role:%' THEN
      CASE WHEN EXISTS (SELECT 1 FROM authz.roles r WHERE 'role:' || r.id = p_relation AND r.object_type = p_type)
                AND EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'share') THEN 'share' END
    ELSE (SELECT min(s.shared_by) FROM authz_int.shared_relations s JOIN authz_int.perms pm
            ON pm.type = s.object_type AND pm.perm = s.shared_by
          WHERE s.object_type = p_type AND s.relation = p_relation AND (p_subject IS NULL OR s.subject = p_subject))
  END $f$;
CREATE FUNCTION authz_int.may_manage(p_type text, p_id text, p_relation text, p_subject text DEFAULT NULL)
RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_perm text := authz_int.manage_perm(p_type, p_relation, p_subject);
BEGIN
  IF authz_int.caller_is_admin() THEN RETURN true; END IF;
  RETURN v_perm IS NOT NULL AND EXISTS (SELECT 1 FROM authz.principal()) AND coalesce(authz.can(p_type, p_id, v_perm), false);
END $f$;
-- The subject key of a share (as the policy writes it: user, team#member, user:*, anyone, link)
CREATE FUNCTION authz_int.subject_key(p_type text, p_id text, p_relation text) RETURNS text
LANGUAGE sql IMMUTABLE AS $f$
  SELECT CASE WHEN p_type IN ('anyone', 'link') THEN p_type
              WHEN p_id = '*' AND p_relation = '' THEN p_type || ':*'
              WHEN p_relation <> '' THEN p_type || '#' || p_relation
              ELSE p_type END $f$;

-- Ask for access: SELECT authz.request_access('folder', '3', 'viewer', 'for the audit', '7 days')
CREATE OR REPLACE FUNCTION authz.request_access(p_type text, p_id text, p_relation text, p_reason text,
  p_duration interval DEFAULT NULL) RETURNS bigint
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id bigint; v_tbl text;
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  PERFORM authz_int.check_writable();
  IF authz.uid() IS NULL THEN RAISE EXCEPTION 'sign in first' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ701'; END IF;
  IF coalesce(btrim(p_reason), '') = '' THEN RAISE EXCEPTION 'say why you need it' USING HINT = 'rowstile help AZ710'; END IF;
  IF p_duration IS NOT NULL AND p_duration <= interval '0' THEN RAISE EXCEPTION 'the duration must be positive' USING HINT = 'rowstile help AZ710'; END IF;
  SELECT tbl INTO v_tbl FROM authz_int.types WHERE name = p_type;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'no type % in the policy', p_type USING HINT = 'rowstile help AZ707'; END IF;
  IF authz_int.manage_perm(p_type, p_relation, CASE WHEN p_relation LIKE 'role:%' THEN NULL ELSE 'user' END) IS NULL
     OR (p_relation LIKE 'role:%' AND NOT EXISTS (SELECT 1 FROM authz_int.role_subjects
                                                  WHERE object_type = p_type AND subject = 'user')) THEN
    RAISE EXCEPTION 'the policy does not allow sharing %.% with a user', p_type, p_relation USING HINT = 'rowstile help AZ706';
  END IF;
  -- no check that the object exists: that would tell people which hidden objects do. A request
  -- for a missing object simply never reaches anyone who could approve it.
  INSERT INTO authz.requests (object_type, object_id, relation, requester, reason, duration)
  VALUES (p_type, p_id, p_relation, authz.uid()::text, p_reason, p_duration) RETURNING id INTO v_id;
  PERFORM authz_int.audit('request_access', p_type, p_id, p_relation, 'user', authz.uid()::text, '',
                          jsonb_build_object('request', v_id, 'duration', p_duration));
  PERFORM pg_notify('authz_requests', v_id::text);
  RETURN v_id;
END $f$;
CREATE OR REPLACE FUNCTION authz.request_access(p_type text, p_id bigint, p_relation text, p_reason text,
  p_duration interval DEFAULT NULL) RETURNS bigint LANGUAGE sql AS
  $$ SELECT authz.request_access(p_type, p_id::text, p_relation, p_reason, p_duration) $$;

-- Requests the current user may decide (they may share that relation on the object), and their own
CREATE OR REPLACE FUNCTION authz.pending_requests()
RETURNS TABLE (id bigint, object_type text, object_id text, relation text, requester text, reason text,
               duration interval, created_at timestamptz, mine boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
  SELECT r.id, r.object_type, r.object_id, r.relation, r.requester, r.reason, r.duration, r.created_at,
         r.requester = authz.uid()::text
  FROM authz.requests r
  WHERE r.status = 'pending' AND authz.uid() IS NOT NULL
    AND (r.requester = authz.uid()::text
         OR (r.requester IS DISTINCT FROM authz.uid()::text
             AND authz_int.may_manage(r.object_type, r.object_id, r.relation,
                                      CASE WHEN r.relation LIKE 'role:%' THEN NULL ELSE 'user' END)))
  ORDER BY r.id $f$;

-- Approve (it becomes a share, made by you, that ends after the requested time) or deny
CREATE OR REPLACE FUNCTION authz.decide_request(p_id bigint, p_approve boolean, p_note text DEFAULT NULL) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r authz.requests;
BEGIN
  PERFORM authz_int.check_writable();
  IF p_approve IS NULL THEN RAISE EXCEPTION 'approve (true) or deny (false)' USING HINT = 'rowstile help AZ710'; END IF;
  SELECT * INTO r FROM authz.requests WHERE id = p_id AND status = 'pending' FOR UPDATE;
  IF r.id IS NULL THEN RAISE EXCEPTION 'no pending request %', p_id USING HINT = 'rowstile help AZ708'; END IF;
  IF authz.uid() IS NULL OR r.requester = authz.uid()::text THEN
    RAISE EXCEPTION 'you cannot decide your own request' USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF NOT authz_int.may_manage(r.object_type, r.object_id, r.relation,
                              CASE WHEN r.relation LIKE 'role:%' THEN NULL ELSE 'user' END) THEN
    RAISE EXCEPTION 'you cannot decide request %', p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF p_approve THEN
    -- authz.share checks again that you may share it, and that you hold what it grants
    PERFORM authz.share(r.object_type, r.object_id, r.relation, 'user', r.requester, '',
                        CASE WHEN r.duration IS NULL THEN NULL ELSE now() + r.duration END);
  END IF;
  UPDATE authz.requests SET status = CASE WHEN p_approve THEN 'approved' ELSE 'denied' END,
    decided_by = authz.uid()::text, decided_at = now(), note = p_note WHERE id = p_id;
  PERFORM authz_int.audit(CASE WHEN p_approve THEN 'approve_request' ELSE 'deny_request' END, r.object_type,
    r.object_id, r.relation, 'user', r.requester, '', jsonb_build_object('request', p_id, 'note', p_note));
END $f$;
CREATE OR REPLACE FUNCTION authz.cancel_request(p_id bigint) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
BEGIN
  PERFORM authz_int.check_writable();
  UPDATE authz.requests SET status = 'cancelled', decided_at = now()
  WHERE id = p_id AND status = 'pending' AND requester = authz.uid()::text;
  IF NOT FOUND THEN RAISE EXCEPTION 'no pending request % of yours', p_id USING HINT = 'rowstile help AZ708'; END IF;
END $f$;

-- Emergency access: people who hold 'break_glass' on an object give themselves a relation on it
-- for a short time (one day at most); it is audited and announced on channel authz_alerts
-- (the notification carries the audit row's id; the details stay in authz.audit)
CREATE OR REPLACE FUNCTION authz.break_glass(p_type text, p_id text, p_relation text, p_reason text,
  p_duration interval DEFAULT interval '1 hour') RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE g authz.shares; v_until timestamptz; v_audit bigint;
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  PERFORM authz_int.check_writable();
  IF coalesce(btrim(p_reason), '') = '' THEN RAISE EXCEPTION 'say why (it is kept in the audit trail)' USING HINT = 'rowstile help AZ710'; END IF;
  IF p_duration IS NULL OR p_duration <= interval '0' OR p_duration > interval '1 day' THEN
    RAISE EXCEPTION 'emergency access lasts more than nothing and one day at most' USING HINT = 'rowstile help AZ710';
  END IF;
  IF authz.uid() IS NULL
     OR NOT EXISTS (SELECT 1 FROM authz_int.perms WHERE type = p_type AND perm = 'break_glass')
     OR NOT authz.can(p_type, p_id, 'break_glass') THEN
    RAISE EXCEPTION 'you cannot break the glass on % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM authz_int.shared_relations WHERE object_type = p_type AND relation = p_relation
                 AND subject = 'user') THEN
    RAISE EXCEPTION 'the policy does not allow sharing %.% with a user', p_type, p_relation USING HINT = 'rowstile help AZ706';
  END IF;
  v_until := now() + p_duration;
  PERFORM set_config('authz_ctx.reason', p_reason, true);
  SELECT * INTO g FROM authz.shares WHERE object_type = p_type AND object_id = p_id AND relation = p_relation
    AND subject_type = 'user' AND subject_id = authz.uid()::text AND subject_relation = '' FOR UPDATE;
  IF g.object_id IS NULL THEN
    INSERT INTO authz.shares (object_type, object_id, relation, subject_type, subject_id, subject_relation,
                              expires_at, created_by)
    VALUES (p_type, p_id, p_relation, 'user', authz.uid()::text, '', v_until, authz.uid()::text);
  ELSIF g.caveat IS NOT NULL OR (g.starts_at IS NOT NULL AND g.starts_at > now())
        OR (g.expires_at IS NOT NULL AND g.expires_at < v_until) THEN
    -- a share that would not let them in now becomes an unconditional one until then (the old one is in the audit)
    UPDATE authz.shares SET expires_at = CASE WHEN g.expires_at IS NULL THEN v_until ELSE greatest(g.expires_at, v_until) END,
      starts_at = NULL, caveat = NULL, caveat_args = NULL
    WHERE object_type = p_type AND object_id = p_id AND relation = p_relation
      AND subject_type = 'user' AND subject_id = authz.uid()::text AND subject_relation = '';
  END IF;
  PERFORM authz_int.audit('break_glass', p_type, p_id, p_relation, 'user', authz.uid()::text, '',
                          jsonb_build_object('until', v_until, 'previous_share', CASE WHEN g.object_id IS NULL THEN NULL
                                             ELSE to_jsonb(g) - 'subject_id' END));
  SELECT max(id) INTO v_audit FROM authz.audit WHERE action = 'break_glass' AND txid = txid_current();
  PERFORM pg_notify('authz_alerts', json_build_object('audit_id', v_audit, 'action', 'break_glass')::text);
END $f$;
CREATE OR REPLACE FUNCTION authz.break_glass(p_type text, p_id bigint, p_relation text, p_reason text,
  p_duration interval DEFAULT interval '1 hour') RETURNS void LANGUAGE sql AS
  $$ SELECT authz.break_glass(p_type, p_id::text, p_relation, p_reason, p_duration) $$;

-- Access reviews: snapshot the shares on an object; reviewers keep or revoke each; closing applies it.
-- Starting one needs 'share' on the object (or being an administrator); revoking an item needs
-- what unsharing it needs.
CREATE OR REPLACE FUNCTION authz.start_review(p_type text, p_id text, p_closes_at timestamptz DEFAULT now() + interval '14 days')
RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_id bigint;
BEGIN
  p_id := authz_int.canon(p_type, p_id);
  PERFORM authz_int.check_writable();
  IF NOT authz_int.may_inspect(p_type, p_id) THEN
    RAISE EXCEPTION 'you cannot review % %', p_type, p_id USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  INSERT INTO authz.reviews (object_type, object_id, created_by, closes_at)
  VALUES (p_type, p_id, authz.uid()::text, p_closes_at) RETURNING id INTO v_id;
  INSERT INTO authz.review_items (review_id, item, relation, subject_type, subject_id, subject_relation, expires_at)
  SELECT v_id, row_number() OVER (ORDER BY g.created_at, g.relation, g.subject_type, g.subject_id), g.relation,
         g.subject_type, g.subject_id, g.subject_relation, g.expires_at
  FROM authz.shares g WHERE g.object_type = p_type AND g.object_id = p_id;
  PERFORM authz_int.audit('start_review', p_type, p_id, NULL, NULL, NULL, NULL, jsonb_build_object('review', v_id));
  RETURN v_id;
END $f$;
CREATE OR REPLACE FUNCTION authz.start_review(p_type text, p_id bigint, p_closes_at timestamptz DEFAULT now() + interval '14 days')
RETURNS bigint LANGUAGE sql AS
  $$ SELECT authz.start_review(p_type, p_id::text, p_closes_at) $$;
CREATE OR REPLACE FUNCTION authz.review_items(p_review bigint)
RETURNS TABLE (item int, relation text, subject_type text, subject_id text, subject_relation text,
               expires_at timestamptz, keep boolean, decided_by text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.reviews;
BEGIN
  SELECT * INTO v FROM authz.reviews WHERE id = p_review;
  IF v.id IS NULL OR NOT authz_int.may_inspect(v.object_type, v.object_id) THEN
    RAISE EXCEPTION 'you cannot see review %', p_review USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  RETURN QUERY SELECT i.item, i.relation, i.subject_type,
    CASE WHEN i.subject_type = 'link' THEN '(link)' ELSE i.subject_id END, i.subject_relation, i.expires_at, i.keep,
    i.decided_by FROM authz.review_items i WHERE i.review_id = p_review ORDER BY i.item;
END $f$;
CREATE OR REPLACE FUNCTION authz.review_decide(p_review bigint, p_item int, p_keep boolean) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.reviews; i authz.review_items;
BEGIN
  PERFORM authz_int.check_writable();
  SELECT * INTO v FROM authz.reviews WHERE id = p_review AND closed_at IS NULL;
  IF v.id IS NULL OR NOT authz_int.may_inspect(v.object_type, v.object_id) THEN
    RAISE EXCEPTION 'you cannot decide in review %', p_review USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  SELECT * INTO i FROM authz.review_items WHERE review_id = p_review AND item = p_item;
  IF i.item IS NULL THEN RAISE EXCEPTION 'no item % in review %', p_item, p_review USING HINT = 'rowstile help AZ708'; END IF;
  IF NOT authz_int.may_manage(v.object_type, v.object_id, i.relation,
                              authz_int.subject_key(i.subject_type, i.subject_id, i.subject_relation)) THEN
    RAISE EXCEPTION 'you cannot decide on % in review % (you could not unshare it)', i.relation, p_review
      USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  UPDATE authz.review_items SET keep = p_keep, decided_by = authz.uid()::text, decided_at = now()
  WHERE review_id = p_review AND item = p_item;
END $f$;
-- Close: revoke what reviewers marked (and, if asked, whatever nobody decided and you could unshare)
CREATE OR REPLACE FUNCTION authz.close_review(p_review bigint, p_revoke_undecided boolean DEFAULT false) RETURNS int
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v authz.reviews; n int;
BEGIN
  PERFORM authz_int.check_writable();
  SELECT * INTO v FROM authz.reviews WHERE id = p_review AND closed_at IS NULL FOR UPDATE;
  IF v.id IS NULL OR NOT authz_int.may_inspect(v.object_type, v.object_id) THEN
    RAISE EXCEPTION 'you cannot close review %', p_review USING ERRCODE = 'insufficient_privilege', HINT = 'rowstile help AZ705';
  END IF;
  PERFORM set_config('authz_ctx.reason', 'access review ' || p_review, true);
  -- items marked 'revoke' were decided by someone allowed to unshare them; undecided ones need you to be
  DELETE FROM authz.shares g USING authz.review_items i
  WHERE i.review_id = p_review
    AND (i.keep = false OR (p_revoke_undecided AND i.keep IS NULL
         AND authz_int.may_manage(v.object_type, v.object_id, i.relation,
                                  authz_int.subject_key(i.subject_type, i.subject_id, i.subject_relation))))
    AND g.object_type = v.object_type AND g.object_id = v.object_id AND g.relation = i.relation
    AND g.subject_type = i.subject_type AND g.subject_id = i.subject_id AND g.subject_relation = i.subject_relation;
  GET DIAGNOSTICS n = ROW_COUNT;
  UPDATE authz.reviews SET closed_at = now() WHERE id = p_review;
  PERFORM authz_int.audit('close_review', v.object_type, v.object_id, NULL, NULL, NULL, NULL,
                          jsonb_build_object('review', p_review, 'revoked', n));
  RETURN n;
END $f$;

-- The search path the functions that evaluate the policy's own SQL run with (SET search_path FROM CURRENT)
CREATE FUNCTION authz_int.policy_path() RETURNS name[]
LANGUAGE sql STABLE SET search_path FROM CURRENT AS $f$ SELECT pg_catalog.current_schemas(false) $f$;

-- Leaks: SELECT * FROM authz.lint()  (administrators; run after schema changes)
CREATE OR REPLACE FUNCTION authz.lint() RETURNS TABLE (severity text, object text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE r record; v_role oid := to_regrole('starter_app');
BEGIN
  IF v_role IS NULL THEN
    severity := 'error'; object := 'starter_app'; problem := 'the app role does not exist'; RETURN NEXT; RETURN;
  END IF;
  -- the app role itself
  FOR r IN SELECT rolsuper, rolbypassrls FROM pg_roles WHERE oid = v_role AND (rolsuper OR rolbypassrls) LOOP
    severity := 'error'; object := 'starter_app';
    problem := 'is a superuser or has BYPASSRLS: row-level security does not apply to it at all'; RETURN NEXT;
  END LOOP;
  FOR r IN SELECT p.oid::regrole AS parent FROM pg_roles p
           WHERE p.oid <> v_role AND (p.rolsuper OR p.rolbypassrls) AND pg_has_role(v_role, p.oid, 'MEMBER') LOOP
    severity := 'error'; object := 'starter_app';
    problem := format('is a member of %s, which bypasses row-level security', r.parent); RETURN NEXT;
  END LOOP;
  -- rowstile's own objects: nobody but the owner uses them, except for what the policy grants
  FOR r IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = 'starter_app'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = 'starter_app'::regrole AND c.relnamespace = 'authz_gen'::regnamespace AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, 'starter_app'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = 'starter_app'::regrole)
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = 'starter_app'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.create_role(text, bigint, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.roles_of(text, bigint)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.start_review(text, bigint, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.list_links(text, bigint)', 'authz.revoke_link(text, bigint, text)', 'authz.can(text, bigint, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.perms(text, bigint)']::regprocedure[])) LOOP
    severity := 'error'; object := r.object;
    problem := format('%s holds %s on it, which the policy doesn''t give (a default privilege of the owner, or a grant made since the last apply): the next apply takes it back, or %s', r.who, r.privilege, r.stmt);
    RETURN NEXT;
  END LOOP;
  -- schemas on the search path of the functions that run as the owner, which others may create in
  FOR r IN SELECT n.nspname::text AS schema, w.who
FROM pg_catalog.unnest(authz_int.policy_path()) s(name) JOIN pg_catalog.pg_namespace n ON n.nspname = s.name,
LATERAL (SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_catalog.aclexplode(n.nspacl) a
                                  WHERE a.grantee = 0 AND a.privilege_type = 'CREATE') THEN 'PUBLIC'
                ELSE (SELECT pg_catalog.string_agg(ro.rolname::text, ', ' ORDER BY ro.rolname) FROM pg_catalog.pg_roles ro
                      WHERE pg_catalog.has_schema_privilege(ro.oid, n.oid, 'CREATE') AND NOT ro.rolsuper
                        AND ro.rolname <> 'pg_database_owner' AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT nspowner FROM pg_namespace WHERE nspname = 'authz_int'), 'MEMBER')
                        AND NOT pg_catalog.pg_has_role(ro.oid, (SELECT d.datdba FROM pg_catalog.pg_database d
                                                               WHERE d.datname = pg_catalog.current_database()), 'MEMBER'))
                END AS who) w
-- a temporary schema is the session's own, and never searched for functions or operators
WHERE w.who IS NOT NULL AND n.nspname !~ '^pg_(toast_)?temp_' LOOP
    severity := 'error'; object := r.schema;
    problem := format('is on the search path of rowstile''s functions that run as the owner, and %s may create in it: a function there can take the place of a built-in one and run as the owner. REVOKE CREATE ON SCHEMA %I FROM %s, or apply with a search path without it', r.who, r.schema, r.who);
    RETURN NEXT;
  END LOOP;
  -- governed tables
  FOR r IN SELECT c.oid::regclass AS tbl, c.relrowsecurity, c.relforcerowsecurity, c.relowner,
                  c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x) AS governed
           FROM pg_class c WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"', '"app"."teams"', '"app"."users"']::text[]) x) LOOP
    IF r.relowner = v_role OR pg_has_role(v_role, r.relowner, 'MEMBER') THEN
      IF NOT r.relforcerowsecurity THEN
        severity := 'error'; object := r.tbl::text;
        problem := format('is owned by %s (or a role it belongs to): owners skip row-level security unless you ALTER TABLE %s FORCE ROW LEVEL SECURITY', 'starter_app', r.tbl);
        RETURN NEXT;
      END IF;
    END IF;
    IF NOT r.relrowsecurity AND r.governed THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('row-level security is off, so the policy''s rules don''t apply to it: %s reads and writes every row it has privileges on. Apply the policy again (it turns it on), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', 'starter_app', r.tbl);
      RETURN NEXT;
    ELSIF NOT r.relrowsecurity AND has_table_privilege(v_role, r.tbl, 'SELECT') THEN
      severity := 'info'; object := r.tbl::text;
      problem := format('%s may read every row (the policy has no rules for this table): fine for a directory, otherwise add rules', 'starter_app');
      RETURN NEXT;
    END IF;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which skips row-level security: REVOKE TRUNCATE ON %s FROM %s', 'starter_app', r.tbl, 'starter_app');
      RETURN NEXT;
    END IF;
  END LOOP;
  -- policies on governed tables that rowstile didn't make (left from before, or made by a migration) and that
  -- apply to the app role: Postgres joins permissive policies with OR, so one widens what the rules allow
  FOR r IN SELECT p.polname, p.polrelid::regclass AS tbl, p.polpermissive,
                  CASE p.polcmd WHEN 'r' THEN 'select' WHEN 'a' THEN 'insert' WHEN 'w' THEN 'update'
                                WHEN 'd' THEN 'delete' ELSE 'every command' END AS cmd
           FROM pg_policy p
           LEFT JOIN pg_description d ON d.objoid = p.oid AND d.classoid = 'pg_policy'::regclass
           WHERE p.polrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x)
             AND coalesce(d.description, '') NOT IN ('rowstile', 'rowfence', 'authzc')
             AND p.polname NOT IN ('authz_select', 'authz_insert', 'authz_update', 'authz_delete')
             AND EXISTS (SELECT 1 FROM unnest(p.polroles) o
                         WHERE CASE WHEN o = 0 THEN true ELSE pg_has_role(v_role, o, 'MEMBER') END)
           ORDER BY p.polrelid::regclass::text, p.polname LOOP
    object := r.tbl::text;
    IF r.polpermissive THEN
      severity := 'error';
      problem := format('the policy %I (%s) on it is not rowstile''s: Postgres joins a table''s policies with OR, so it lets %s through whatever the rules say. DROP POLICY %I ON %s, and say what it allowed in the policy file', r.polname, r.cmd, 'starter_app', r.polname, r.tbl);
    ELSE
      severity := 'info';
      problem := format('the restrictive policy %I (%s) on it is not rowstile''s: %s gets less than the rules give, and a write it refuses fails with Postgres''s own message, not a reason', r.polname, r.cmd, 'starter_app');
    END IF;
    RETURN NEXT;
  END LOOP;
  -- tables beside the policy's (in their schemas) that it doesn't name: nothing filters what the app role reads there
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind IN ('r', 'p') AND NOT c.relispartition AND NOT c.relrowsecurity
             AND c.relnamespace IN (SELECT k.relnamespace FROM unnest(ARRAY['"app"."documents"', '"app"."teams"', '"app"."users"', '"app"."team_members"']::text[]) x
                                    JOIN pg_class k ON k.oid = to_regclass(x))
             AND c.oid NOT IN (SELECT to_regclass(x)::oid FROM unnest(ARRAY['"app"."documents"', '"app"."teams"', '"app"."users"', '"app"."team_members"']::text[]) x
                               WHERE to_regclass(x) IS NOT NULL)
             AND has_any_column_privilege(v_role, c.oid, 'SELECT')
           ORDER BY c.oid::regclass::text LOOP
    severity := 'info'; object := r.tbl::text;
    problem := format('%s may read every row, and the policy doesn''t name this table: fine for a lookup table, otherwise give it a type and rules', 'starter_app');
    RETURN NEXT;
  END LOOP;
  -- partitions and inheritance children: used directly, they skip the rules and the triggers of the table above
  -- (apply turns row-level security on for the ones there are then; later ones are found here)
  FOR r IN WITH RECURSIVE d(oid, top, governed) AS (
             SELECT i.inhrelid, i.inhparent, x.governed FROM pg_inherits i
             JOIN (SELECT to_regclass(t) AS tbl, true AS governed FROM unnest(ARRAY['"app"."documents"']::text[]) t
                   UNION ALL SELECT to_regclass(t), false FROM unnest(ARRAY['"app"."team_members"']::text[]) t) x
               ON i.inhparent = x.tbl
             UNION SELECT i.inhrelid, d.top, d.governed FROM pg_inherits i JOIN d ON i.inhparent = d.oid)
           SELECT d.oid::regclass AS part, d.top::regclass AS tbl, d.governed, k.relrowsecurity
           FROM d JOIN pg_class k ON k.oid = d.oid LOOP
    IF has_table_privilege(v_role, r.part, 'TRUNCATE') THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may TRUNCATE it, which skips row-level security and %s''s triggers: REVOKE TRUNCATE ON %s FROM %s', r.tbl, 'starter_app', r.tbl, r.part, 'starter_app');
      RETURN NEXT;
    END IF;
    IF NOT r.relrowsecurity AND (has_table_privilege(v_role, r.part, 'INSERT') OR has_table_privilege(v_role, r.part, 'UPDATE')
                                 OR has_table_privilege(v_role, r.part, 'DELETE')
                                 OR (r.governed AND has_table_privilege(v_role, r.part, 'SELECT'))) THEN
      severity := 'error'; object := r.part::text;
      problem := format('is a partition of %s (or inherits from it), and %s may use it directly, without %s''s rules or the triggers that keep inheritance and the audit current: apply the policy again (it turns row-level security on for it), or ALTER TABLE %s ENABLE ROW LEVEL SECURITY', r.tbl, 'starter_app', r.tbl, r.part);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- unique constraints on governed tables tell people that rows they cannot see exist
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisunique AND NOT i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x)
             AND has_table_privilege(v_role, i.indrelid, 'INSERT') LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('a unique index on %s: inserting a duplicate fails even when the existing row is hidden, which tells the user it exists', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- primary keys the app role may choose (a column it may insert or update, not GENERATED ALWAYS): the same
  FOR r IN SELECT i.indexrelid::regclass AS idx, i.indrelid::regclass AS tbl
           FROM pg_index i WHERE i.indisprimary
             AND i.indrelid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x)
             AND EXISTS (SELECT 1 FROM pg_attribute a
                         WHERE a.attrelid = i.indrelid AND a.attnum = ANY (i.indkey) AND a.attidentity <> 'a'
                           AND (has_column_privilege(v_role, i.indrelid, a.attnum, 'INSERT')
                                OR has_column_privilege(v_role, i.indrelid, a.attnum, 'UPDATE'))) LOOP
    severity := 'info'; object := r.idx::text;
    problem := format('the primary key of %s, which %s may choose: an insert with the id of a hidden row fails, which tells the user it exists. Let the database make the ids (GENERATED ALWAYS AS IDENTITY, or random uuids), or revoke INSERT and UPDATE on the key', r.tbl, 'starter_app');
    RETURN NEXT;
  END LOOP;
  -- masked columns must only be readable through their view
  FOR r IN SELECT m.tbl, m.col, m.view FROM authz_int.masked_columns m
           WHERE CASE WHEN EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(m.tbl) AND a.attname = m.col
                                   AND a.attnum > 0 AND NOT a.attisdropped)
                      THEN has_column_privilege(v_role, m.tbl, m.col, 'SELECT') ELSE false END LOOP
    severity := 'error'; object := to_regclass(r.tbl)::text || '.' || r.col;
    problem := format('the policy masks it, but %s may read it from the table (a GRANT to the role, a role it belongs to, or PUBLIC): read it through %s and revoke that', 'starter_app', r.view);
    RETURN NEXT;
  END LOOP;
  -- tables holding relationships (memberships, links) the app role may change directly
  FOR r IN SELECT to_regclass(x) AS tbl FROM unnest(ARRAY['"app"."team_members"']::text[]) x LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF has_table_privilege(v_role, r.tbl, 'TRUNCATE') THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may TRUNCATE it, which empties memberships without row-level security: REVOKE TRUNCATE ON %s FROM %s', 'starter_app', r.tbl, 'starter_app');
      RETURN NEXT;
    END IF;
    IF (has_table_privilege(v_role, r.tbl, 'INSERT') OR has_table_privilege(v_role, r.tbl, 'UPDATE')
        OR has_table_privilege(v_role, r.tbl, 'DELETE'))
       AND NOT (SELECT relrowsecurity FROM pg_class WHERE oid = r.tbl) THEN
      severity := 'error'; object := r.tbl::text;
      problem := format('%s may change it, and it decides who is in what: anyone could add themselves. Revoke the write privileges, or give it rules', 'starter_app');
      RETURN NEXT;
    END IF;
  END LOOP;
  -- columns that grant a relation, changed by anyone who may update the row
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, what, loc, ask)
           WHERE tbl IS NOT NULL LOOP
    IF EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass(r.tbl) AND a.attname = r.col
               AND a.attnum > 0 AND NOT a.attisdropped)
       AND has_column_privilege(v_role, r.tbl, r.col, 'UPDATE') THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('grants %s (%s), and anyone who may update the row may change it: add a rule such as "update %s : %s"', r.what, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.ask);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- JIT for the app role: checks are many small subplans, which JIT may spend longer compiling than running
  IF coalesce((SELECT split_part(c, '=', 2) FROM pg_db_role_setting s, unnest(s.setconfig) c
               WHERE s.setrole = v_role AND c LIKE 'jit=%'
                 AND s.setdatabase IN (0, (SELECT d.oid FROM pg_database d WHERE d.datname = current_database()))
               ORDER BY s.setdatabase DESC LIMIT 1), current_setting('jit')) IN ('on', 'true', '1') THEN
    severity := 'performance'; object := 'starter_app';
    problem := format('runs with JIT on: permission checks are many small subplans, and JIT can take longer to compile a read than to run it (a third of a second for a large one): ALTER ROLE %s SET jit = off', 'starter_app');
    RETURN NEXT;
  END IF;
  -- rules for a command the app role has no privilege for (one column's is enough for a read, an insert or
  -- an update: the app may write some columns only)
  FOR r IN SELECT to_regclass(v.tbl) AS tbl, v.cmd FROM (VALUES ('"app"."documents"', 'delete'), ('"app"."documents"', 'insert'), ('"app"."documents"', 'select'), ('"app"."documents"', 'update')) v(tbl, cmd)
           WHERE v.tbl IS NOT NULL LOOP
    CONTINUE WHEN r.tbl IS NULL;
    IF r.cmd = 'delete' THEN
      CONTINUE WHEN has_table_privilege(v_role, r.tbl, 'DELETE');
    ELSE
      CONTINUE WHEN has_any_column_privilege(v_role, r.tbl, r.cmd);
    END IF;
    severity := 'warning'; object := r.tbl::text;
    problem := format('the policy has a rule for %s, but %s has no %s privilege on the table: the rule never applies, and the statement fails with Postgres''s own "permission denied for table". GRANT %s ON %s TO %s, or make the rule "%s : nobody"', r.cmd, 'starter_app', upper(r.cmd), upper(r.cmd), r.tbl, 'starter_app', r.cmd);
    RETURN NEXT;
  END LOOP;
  -- relations named like a type that signs in
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text)) v(type, rel, loc)
           WHERE type IS NOT NULL LOOP
    severity := 'info'; object := r.type || '.' || r.rel;
    problem := format('is named like the type %s (%s), which signs in: alone in a rule it reads like any %s, and it is this row''s. A name that says what the relation is (author, owner) reads better', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.rel);
    RETURN NEXT;
  END LOOP;
  -- columns that move a row under another, with nothing checking where it moves to
  FOR r IN SELECT * FROM (VALUES (NULL::text, NULL::text, NULL::text, NULL::text)) v(tbl, col, rel, loc)
           WHERE tbl IS NOT NULL LOOP
    IF has_column_privilege(v_role, r.tbl, r.col, 'UPDATE') THEN
      severity := 'warning'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('moves a row under another (%s, %s), and nothing checks where it moves to, so anyone who may update a row may put it inside something they may not change: add a rule such as "update %s after : %s.edit"', r.rel, coalesce((SELECT l.loc FROM authz_gen.policy_lines l WHERE l.what = r.loc), '?'), r.col, r.rel);
      RETURN NEXT;
    END IF;
  END LOOP;
  -- views over governed tables that run with their owner's rights
  FOR r IN SELECT DISTINCT v.oid::regclass AS view, d.refobjid::regclass AS tbl
           FROM pg_depend d JOIN pg_rewrite w ON w.oid = d.objid JOIN pg_class v ON v.oid = w.ev_class
           LEFT JOIN pg_description ds ON ds.objoid = v.oid AND ds.classoid = 'pg_class'::regclass
           WHERE d.classid = 'pg_rewrite'::regclass AND d.refclassid = 'pg_class'::regclass
             AND d.refobjid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"', '"app"."teams"', '"app"."users"', '"app"."team_members"']::text[]) x)
             AND v.oid <> d.refobjid AND v.relkind IN ('v', 'm')
             AND v.relnamespace NOT IN (to_regnamespace('authz_gen'), to_regnamespace('authz_int'))
             AND coalesce(ds.description, '') NOT IN ('rowstile masked view', 'rowfence masked view', 'authzc masked view')
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=true'], false)
             AND NOT coalesce(v.reloptions @> ARRAY['security_invoker=on'], false)
             AND has_table_privilege(v_role, v.oid, 'SELECT') LOOP
    severity := 'error'; object := r.view::text;
    problem := format('%s may read this view of %s, and views run with their owner''s rights, so row-level security does not apply: ALTER VIEW %s SET (security_invoker = on)', 'starter_app', r.tbl, r.view);
    RETURN NEXT;
  END LOOP;
  -- functions that read governed tables as their owner
  FOR r IN SELECT p.oid::regprocedure AS fn FROM pg_proc p
           WHERE p.prosecdef AND p.pronamespace NOT IN (to_regnamespace('authz'), to_regnamespace('authz_int'),
                                                       to_regnamespace('authz_gen'), 'pg_catalog'::regnamespace)
             AND has_function_privilege(v_role, p.oid, 'EXECUTE')
             AND p.prokind IN ('f', 'p')
             AND EXISTS (SELECT 1 FROM unnest(ARRAY['app.documents', 'app.teams', 'app.users', 'app.team_members']::text[]) x
                         WHERE lower(replace(pg_get_functiondef(p.oid), '"', '')) ~
                               ('(from|join|update|into|table|only)\s+(' || lower(split_part(x, '.', 1)) || '\.)?'
                                || lower(split_part(x, '.', 2)) || '([^a-z0-9_$]|$)')) LOOP
    severity := 'warning'; object := r.fn::text;
    problem := 'SECURITY DEFINER, callable by the app role, and seems to use a governed table: it reads rows without row-level security unless its owner is subject to it';
    RETURN NEXT;
  END LOOP;
  -- lookups the permission views make
  FOR r IN SELECT * FROM (VALUES ('"app"."team_members"', 'team_id', 'team.member: find the members of an object'), ('"app"."team_members"', 'user_id', 'team.member: find what a subject is in'), ('"app"."documents"', 'owner_id', 'document.owner: find objects by owner_id')) v(tbl, col, why) WHERE tbl IS NOT NULL LOOP
    CONTINUE WHEN to_regclass(r.tbl) IS NULL;
    -- a plain view can't have an index: the tables under it answer the lookups
    CONTINUE WHEN (SELECT c.relkind FROM pg_class c WHERE c.oid = to_regclass(r.tbl)) = 'v';
    -- an index whose first columns are these (one, or a composite key's, in any order)
    IF NOT EXISTS (SELECT 1 FROM pg_index i
                   WHERE i.indrelid = to_regclass(r.tbl)
                     AND (SELECT array_agg(a.attname::text ORDER BY a.attname)
                          FROM unnest((i.indkey::int2[])[0:cardinality(string_to_array(r.col, ', ')) - 1]) k
                          JOIN pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = k)
                         = (SELECT array_agg(c ORDER BY c) FROM unnest(string_to_array(r.col, ', ')) c)) THEN
      severity := 'performance'; object := to_regclass(r.tbl)::text || '.' || r.col;
      problem := format('no index starts with %s (%s): CREATE INDEX ON %s (%s)',
                        CASE WHEN r.col LIKE '%, %' THEN 'these columns' ELSE 'this column' END, r.why, to_regclass(r.tbl),
                        (SELECT string_agg(quote_ident(c), ', ') FROM unnest(string_to_array(r.col, ', ')) c));
      RETURN NEXT;
    END IF;
  END LOOP;
END $f$;

-- What is wrong with this connection, for the app to check when it starts: SELECT * FROM authz.connection_check()
-- 'error': the rules don't apply to the role this connection runs as; 'performance'; 'info'. No rows: all is well.
CREATE OR REPLACE FUNCTION authz.connection_check() RETURNS TABLE (severity text, problem text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, pg_temp AS $f$
DECLARE v_me oid := to_regrole(authz_int.caller_role()); v_app oid := to_regrole('starter_app'); r record;
BEGIN
  IF (SELECT rolsuper FROM pg_roles WHERE oid = v_me) THEN
    severity := 'error'; problem := format('%s is a superuser: row-level security does not apply to it', v_me::regrole);
    RETURN NEXT; RETURN;
  END IF;
  IF (SELECT rolbypassrls FROM pg_roles WHERE oid = v_me) THEN
    severity := 'error'; problem := format('%s has BYPASSRLS: row-level security does not apply to it', v_me::regrole);
    RETURN NEXT;
  END IF;
  -- a table's owner (or a role with its rights) skips row-level security, unless the table forces it
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x)
             AND NOT c.relforcerowsecurity AND pg_has_role(v_me, c.relowner, 'USAGE') LOOP
    severity := 'error';
    problem := format('%s owns %s (or has its owner''s rights): owners skip row-level security', v_me::regrole, r.tbl);
    RETURN NEXT;
  END LOOP;
  -- a table with rules whose row-level security is off: the rules don't apply
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."documents"']::text[]) x) AND NOT c.relrowsecurity LOOP
    severity := 'error';
    problem := format('row-level security is off on %s: the policy''s rules don''t apply to it', r.tbl);
    RETURN NEXT;
  END LOOP;
  -- a login that switched to the app role (SET ROLE) but is an administrator: RESET ROLE leaves row-level
  -- security, and its sessions are believed without a signature
  FOR r IN SELECT l.oid::regrole AS login FROM pg_roles l, pg_namespace n
           WHERE l.rolname = session_user AND n.nspname = 'authz_int' AND l.oid <> v_me
             AND (l.rolsuper OR l.rolbypassrls OR pg_has_role(l.oid, n.nspowner, 'MEMBER')) LOOP
    severity := 'error';
    problem := format('this connection logs in as %s, a superuser, BYPASSRLS or the policy''s owner, and switched to %s: RESET ROLE leaves row-level security, and who is signed in is believed without a signature. Log in as the app role', r.login, v_me::regrole);
    RETURN NEXT;
  END LOOP;
  IF v_app IS NULL OR NOT pg_has_role(v_me, v_app, 'USAGE') THEN
    severity := 'error';
    problem := format('%s is not the policy''s app role %s, nor a member of it: the rules apply to %s only',
                      v_me::regrole, 'starter_app', 'starter_app');
    RETURN NEXT;
  END IF;
  IF current_setting('jit') = 'on' THEN
    severity := 'performance';
    problem := 'JIT is on: reads through row-level security can spend more time compiling than running (ALTER ROLE ... SET jit = off)';
    RETURN NEXT;
  END IF;
END $f$;

-- Admin check: every inheritance table matches a from-scratch rebuild
CREATE OR REPLACE FUNCTION authz.verify() RETURNS boolean LANGUAGE sql STABLE AS
  $$ SELECT true $$;

-- where each rule, relation and invariant is written, for messages (Core.line_sql)
CREATE TABLE authz_gen.policy_lines (what text PRIMARY KEY, loc text NOT NULL);
INSERT INTO authz_gen.policy_lines VALUES
  ('rule app.documents delete', 'line 24'),
  ('rule app.documents insert', 'line 21'),
  ('rule app.documents update', 'line 22'),
  ('rule app.documents update owner_id', 'line 23'),
  ('share document.editor team#member', 'line 12'),
  ('share document.editor user', 'line 12'),
  ('share document.viewer team#member', 'line 13'),
  ('share document.viewer user', 'line 13');

DO $k$
DECLARE v_old text;
BEGIN
  SELECT string_agg(p.oid::regprocedure || ' (' || (
           SELECT string_agg(DISTINCT pg_catalog.pg_describe_object(d.classid, d.objid, 0), ', ')
           FROM pg_depend d WHERE d.refclassid = 'pg_proc'::regclass AND d.refobjid = p.oid AND d.deptype = 'n') || ')', '; ')
  INTO v_old FROM pg_proc p
  WHERE p.oid || ' ' || p.ctid = ANY (string_to_array(current_setting('authz_ctx.kept_functions', true), ';'));
  PERFORM set_config('authz_ctx.kept_functions', '', true);
  IF v_old IS NOT NULL THEN
    RAISE EXCEPTION 'this policy no longer makes a function that something in the database uses: % [AZ614]', v_old
      USING HINT = 'Drop or change what uses it, then apply again.';
  END IF;
END $k$;

DO $kv$
DECLARE v_old text;
BEGIN
  SELECT string_agg(c.oid::regclass || ' (' || (
           SELECT string_agg(DISTINCT pg_catalog.pg_describe_object(d.classid, d.objid, 0), ', ')
           FROM pg_depend d WHERE d.refclassid = 'pg_class'::regclass AND d.refobjid = c.oid AND d.deptype = 'n'
             AND NOT (d.classid = 'pg_rewrite'::regclass AND d.objid IN (SELECT oid FROM pg_rewrite WHERE ev_class = c.oid))) || ')', '; ')
  INTO v_old FROM pg_class c JOIN pg_description d ON d.objoid = c.oid AND d.classoid = 'pg_class'::regclass
  WHERE c.relkind = 'v' AND d.description IN ('rowstile masked view', 'rowfence masked view', 'authzc masked view') AND c.oid <> ALL (ARRAY[]::oid[]);
  IF v_old IS NOT NULL THEN
    RAISE EXCEPTION 'this policy no longer makes a masked view that something in the database is built on: % [AZ617]', v_old
      USING HINT = 'Drop or change what is built on it, then apply again.';
  END IF;
END $kv$;

-- Tables that had rules before but have none now keep row-level security on
DO $l$
DECLARE t record;
BEGIN
  FOR t IN SELECT o.tbl FROM pg_temp.authz_old_tables o JOIN pg_class c ON c.oid = o.tbl
           WHERE c.relrowsecurity AND NOT EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = o.tbl) LOOP
    RAISE WARNING '% has no rules any more, and row-level security is still on, so the app role sees none of its rows. If that is not what you want: ALTER TABLE % DISABLE ROW LEVEL SECURITY', t.tbl, t.tbl;
  END LOOP;
END $l$;

-- Privileges the policy doesn't give on rowstile's schemas and what is in them are taken back
DO $r$
DECLARE g record; v_taken int := 0;
BEGIN
  FOR g IN SELECT n.nspname::text AS object, gw.who, a.privilege_type AS privilege,
       format('REVOKE %s ON SCHEMA %I FROM %s CASCADE', a.privilege_type, n.nspname, gw.who) AS stmt
  FROM pg_namespace n, aclexplode(n.nspacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE n.nspname IN ('authz', 'authz_gen', 'authz_int') AND a.grantee <> n.nspowner
    AND NOT (a.grantee = 'starter_app'::regrole AND n.nspname <> 'authz_int' AND a.privilege_type = 'USAGE')
UNION ALL
SELECT c.oid::regclass::text, gw.who, a.privilege_type,
       format('REVOKE %s ON %s %s FROM %s CASCADE', a.privilege_type, CASE c.relkind WHEN 'S' THEN 'SEQUENCE' ELSE 'TABLE' END,
              c.oid::regclass, gw.who)
  FROM pg_class c, aclexplode(c.relacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> c.relowner
    AND NOT (a.grantee = 'starter_app'::regrole AND c.relnamespace = 'authz_gen'::regnamespace AND a.privilege_type = 'SELECT')
UNION ALL
SELECT format('%s (%I)', c.oid::regclass, att.attname), gw.who, a.privilege_type,
       format('REVOKE %s (%I) ON %s FROM %s CASCADE', a.privilege_type, att.attname, c.oid::regclass, gw.who)
  FROM pg_class c JOIN pg_attribute att ON att.attrelid = c.oid, aclexplode(att.attacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND att.attacl IS NOT NULL
UNION ALL
SELECT p.oid::regprocedure::text, gw.who, a.privilege_type,
       format('REVOKE %s ON ROUTINE %s FROM %s CASCADE', a.privilege_type, p.oid::regprocedure, gw.who)
  FROM pg_proc p, aclexplode(p.proacl) a, LATERAL (SELECT CASE a.grantee WHEN 0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END AS who) gw
  WHERE p.pronamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_gen', 'authz_int')) AND a.grantee <> p.proowner
    AND NOT (p.pronamespace = 'authz_int'::regnamespace AND a.grantee IN (0, 'starter_app'::regrole))
    AND NOT (p.pronamespace = 'authz_gen'::regnamespace AND a.grantee = 'starter_app'::regrole)
    AND NOT (p.pronamespace = 'authz'::regnamespace AND a.grantee = 'starter_app'::regrole AND p.oid = ANY (ARRAY['authz.uid()', 'authz.principal()', 'authz.ctx(text)', 'authz.link_hashes()', 'authz.act_as(text, text)', 'authz.connection_check()', 'authz.can(text, text, text)', 'authz.list(text, text, text, integer)', 'authz.perms(text, text)', 'authz.perms_of(text, text[])', 'authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb)', 'authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb)', 'authz.unshare(text, text, text, text, text, text)', 'authz.unshare(text, bigint, text, text, bigint, text)', 'authz.unshare(text, bigint, text, text, text, text)', 'authz.create_link(text, text, text, timestamptz)', 'authz.create_link(text, bigint, text, timestamptz)', 'authz.list_links(text, text)', 'authz.revoke_link(text, text, text)', 'authz.create_role(text, text, text, text, text[])', 'authz.create_role(text, bigint, text, text, text[])', 'authz.set_role_permissions(bigint, text[])', 'authz.delete_role(bigint)', 'authz.roles_of(text, text)', 'authz.roles_of(text, bigint)', 'authz.who(text, text, text)', 'authz.explain(text, text, text, text)', 'authz.list_shares(text, text)', 'authz.explain_rule(text, text, text, jsonb)', 'authz.who_among(text, text, text, text[], text)', 'authz.create_api_key(text, text, timestamptz, text, text)', 'authz.list_api_keys(text, text)', 'authz.revoke_api_key(bigint)', 'authz.login_key(text)', 'authz.login_jwt(text)', 'authz.view_as(text, text)', 'authz.request_access(text, text, text, text, interval)', 'authz.request_access(text, bigint, text, text, interval)', 'authz.pending_requests()', 'authz.decide_request(bigint, boolean, text)', 'authz.cancel_request(bigint)', 'authz.break_glass(text, text, text, text, interval)', 'authz.break_glass(text, bigint, text, text, interval)', 'authz.start_review(text, text, timestamptz)', 'authz.start_review(text, bigint, timestamptz)', 'authz.review_items(bigint)', 'authz.review_decide(bigint, integer, boolean)', 'authz.close_review(bigint, boolean)', 'authz.who(text, bigint, text)', 'authz.explain(text, bigint, text, text)', 'authz.list_shares(text, bigint)', 'authz.list_links(text, bigint)', 'authz.revoke_link(text, bigint, text)', 'authz.can(text, bigint, text)', 'authz.who_among(text, bigint, text, text[], text)', 'authz.perms(text, bigint)']::regprocedure[])) LOOP
    EXECUTE g.stmt;
    v_taken := v_taken + 1;
  END LOOP;
  IF v_taken > 0 THEN
    RAISE WARNING 'took back % privileges on rowstile''s schemas that the policy doesn''t give (default privileges of the owner, or grants made since the last apply)', v_taken;
  END IF;
END $r$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz FROM PUBLIC;

GRANT USAGE ON SCHEMA authz, authz_gen TO starter_app;

GRANT SELECT ON ALL TABLES IN SCHEMA authz_gen TO starter_app;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA authz_gen FROM PUBLIC;

GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA authz_gen TO starter_app;

GRANT EXECUTE ON FUNCTION
  authz.uid(),
  authz.principal(),
  authz.ctx(text),
  authz.link_hashes(),
  authz.act_as(text, text),
  authz.connection_check(),
  authz.can(text, text, text),
  authz.list(text, text, text, integer),
  authz.perms(text, text),
  authz.perms_of(text, text[]),
  authz.share(text, text, text, text, text, text, timestamptz, timestamptz, text, jsonb),
  authz.share(text, bigint, text, text, bigint, text, timestamptz, timestamptz, text, jsonb),
  authz.share(text, bigint, text, text, text, text, timestamptz, timestamptz, text, jsonb),
  authz.unshare(text, text, text, text, text, text),
  authz.unshare(text, bigint, text, text, bigint, text),
  authz.unshare(text, bigint, text, text, text, text),
  authz.create_link(text, text, text, timestamptz),
  authz.create_link(text, bigint, text, timestamptz),
  authz.list_links(text, text),
  authz.revoke_link(text, text, text),
  authz.create_role(text, text, text, text, text[]),
  authz.create_role(text, bigint, text, text, text[]),
  authz.set_role_permissions(bigint, text[]),
  authz.delete_role(bigint),
  authz.roles_of(text, text),
  authz.roles_of(text, bigint),
  authz.who(text, text, text),
  authz.explain(text, text, text, text),
  authz.list_shares(text, text),
  authz.explain_rule(text, text, text, jsonb),
  authz.who_among(text, text, text, text[], text),
  authz.create_api_key(text, text, timestamptz, text, text),
  authz.list_api_keys(text, text),
  authz.revoke_api_key(bigint),
